window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["1CO"]={"book":"1CO","editions":{"fin-biblia1776":[[1,1,"Paavali, kutsuttu Jesuksen Kristuksen apostoliksi Jumalan tahdon kautta, ja Sostenes veli,","Paavali, kutsuttu Jesuksen Kristuksen apostoliksi Jumalan tahdon kautta, ja Sostenes veli,"],[1,2,"Sille Jumalan seurakunnalle, joka on Korintossa, pyhitetyille Kristuksessa Jesuksessa, kutsutuille pyhille ynnä kaikkein niiden kanssa, jotka meidän Herran Jesuksen Kristuksen nimeä avuksensa huutavat, jokaisessa heidän ja meidän siassamme.","Sille Jumalan seurakunnalle, joka on Korintossa, pyhitetyille Kristuksessa Jesuksessa, kutsutuille pyhille ynnä kaikkein niiden kanssa, jotka meidän Herran Jesuksen Kristuksen nimeä avuksensa huutavat, jokaisessa heidän ja meidän siassamme."],[1,3,"Armo olkoon teille ja rauha Jumalalta, meidän isältämme, ja Herralta Jesukselta Kristukselta.","Armo olkoon teille ja rauha Jumalalta, meidän isältämme, ja Herralta Jesukselta Kristukselta."],[1,4,"Minä kiitän Jumalaani aina teidän tähtenne, sen Jumalan armon edestä, joka teille Jesuksessa Kristuksessa annettu on:","Minä kiitän Jumalaani aina teidän tähtenne, sen Jumalan armon edestä, joka teille Jesuksessa Kristuksessa annettu on:"],[1,5,"Että te olette kaikissa rikkaaksi tehdyt hänessä, kaikessa opissa ja kaikessa tuntemisessa.","Että te olette kaikissa rikkaaksi tehdyt hänessä, kaikessa opissa ja kaikessa tuntemisessa."],[1,6,"Sillä todistus Kristuksesta on teissä vahvistettu,","Sillä todistus Kristuksesta on teissä vahvistettu,"],[1,7,"Niin ettei teiltä jossakussa lahjassa mitään puutu, jotka odotatte meidän Herran Jesuksen Kristuksen ilmoitusta,","Niin ettei teiltä jossakussa lahjassa mitään puutu, jotka odotatte meidän Herran Jesuksen Kristuksen ilmoitusta,"],[1,8,"Joka myös teitä loppuun asti vahvistaa, että te olisitte nuhteettomat meidän Herran Jesuksen Kristuksen päivänä.","Joka myös teitä loppuun asti vahvistaa, että te olisitte nuhteettomat meidän Herran Jesuksen Kristuksen päivänä."],[1,9,"Sillä Jumala on uskollinen, jonka kautta te kutsutut olette hänen Poikansa Jesuksen Kristuksen, meidän Herramme yhteyteen.","Sillä Jumala on uskollinen, jonka kautta te kutsutut olette hänen Poikansa Jesuksen Kristuksen, meidän Herramme yhteyteen."],[1,10,"Mutta minä neuvon teitä, rakkaat veljet, meidän Herran Jesuksen Kristuksen nimen kautta, että te kaikki yhdenkaltaisen puheen pitäisitte, ja ettei teidän seassanne eriseuroja olisi, vaan olkaat sovitetut yhdessä mielessä ja yhdessä neuvossa.","Mutta minä neuvon teitä, rakkaat veljet, meidän Herran Jesuksen Kristuksen nimen kautta, että te kaikki yhdenkaltaisen puheen pitäisitte, ja ettei teidän seassanne eriseuroja olisi, vaan olkaat sovitetut yhdessä mielessä ja yhdessä neuvossa."],[1,11,"Sillä minun korvilleni on tullut teistä, rakkaat veljet, Kloen perheen kautta, että riidat ovat teillä keskenänne.","Sillä minun korvilleni on tullut teistä, rakkaat veljet, Kloen perheen kautta, että riidat ovat teillä keskenänne."],[1,12,"Niin minä sanon sitä, että kukin teistä sanoo: minä olen Paavalin, minä olen Apollon, minä Kephaan, minä Kristuksen.","Niin minä sanon sitä, että kukin teistä sanoo: minä olen Paavalin, minä olen Apollon, minä Kephaan, minä Kristuksen."],[1,13,"Lieneekö Kristus jaettu, vai onko Paavali teidän edestänne ristiinnaulittu? eli oletteko te Paavalin nimeen kastetut?","Lieneekö Kristus jaettu, vai onko Paavali teidän edestänne ristiinnaulittu? eli oletteko te Paavalin nimeen kastetut?"],[1,14,"Minä kiitän Jumalaa, etten minä ole yhtään teistä kastanut, vaan Krispuksen ja Gajuksen:","Minä kiitän Jumalaa, etten minä ole yhtään teistä kastanut, vaan Krispuksen ja Gajuksen:"],[1,15,"Ettei kenkään saa sanoa, että minä minun nimeeni ketään kastin.","Ettei kenkään saa sanoa, että minä minun nimeeni ketään kastin."],[1,16,"Minä kastin myös Stephanaan perheen; sitte en minä tiedä, jos minä jonkun muun kastanut olen.","Minä kastin myös Stephanaan perheen; sitte en minä tiedä, jos minä jonkun muun kastanut olen."],[1,17,"Sillä ei Kristus minua lähettänyt kastamaan, vaan evankeliumia saarnaamaan, ei sanan viisaudella, ettei Kristuksen risti turhaan menisi.","Sillä ei Kristus minua lähettänyt kastamaan, vaan evankeliumia saarnaamaan, ei sanan viisaudella, ettei Kristuksen risti turhaan menisi."],[1,18,"Sillä se puhe rististä on niille hulluus, jotka kadotetaan; mutta meille, jotka autuaaksi tulemme, on se Jumalan voima.","Sillä se puhe rististä on niille hulluus, jotka kadotetaan; mutta meille, jotka autuaaksi tulemme, on se Jumalan voima."],[1,19,"Sillä kirjoitettu on: minä kadotan viisasten viisauden, ja ymmärtäväisten ymmärryksen minä hylkään.","Sillä kirjoitettu on: minä kadotan viisasten viisauden, ja ymmärtäväisten ymmärryksen minä hylkään."],[1,20,"Kussas on viisas? kussas on kirjanoppinut? kussas tämän maailman tutkia on? Eikö Jumala ole tämän maailman viisautta hulluudeksi tehnyt?","Kussas on viisas? kussas on kirjanoppinut? kussas tämän maailman tutkia on? Eikö Jumala ole tämän maailman viisautta hulluudeksi tehnyt?"],[1,21,"Sillä että Jumalan viisaudessa ei maailma tuntenut Jumalaa viisauden kautta, niin kelpasi Jumalalle tyhmän saarnan kautta niitä vapahtaa, jotka sen uskovat,","Sillä että Jumalan viisaudessa ei maailma tuntenut Jumalaa viisauden kautta, niin kelpasi Jumalalle tyhmän saarnan kautta niitä vapahtaa, jotka sen uskovat,"],[1,22,"Sentähden että Juudalaiset merkkiä anovat ja Grekiläiset viisautta etsivät;","Sentähden että Juudalaiset merkkiä anovat ja Grekiläiset viisautta etsivät;"],[1,23,"Mutta me saarnaamme ristiinnaulitun Kristuksen Juudalaisille pahennukseksi ja Grekiläisille hulluudeksi.","Mutta me saarnaamme ristiinnaulitun Kristuksen Juudalaisille pahennukseksi ja Grekiläisille hulluudeksi."],[1,24,"Mutta kutsutuille sekä Juudalaisille että Grekiläisille saarnaamme me Kristuksen Jumalan voimaksi ja Jumalan viisaudeksi.","Mutta kutsutuille sekä Juudalaisille että Grekiläisille saarnaamme me Kristuksen Jumalan voimaksi ja Jumalan viisaudeksi."],[1,25,"Sillä Jumalan hulluus on viisaampi kuin ihmiset, ja Jumalan heikkous on väkevämpi kuin ihmiset.","Sillä Jumalan hulluus on viisaampi kuin ihmiset, ja Jumalan heikkous on väkevämpi kuin ihmiset."],[1,26,"Te näette, rakkaat veljet, teidän kutsumisenne, ettei monta lihallista viisasta, ei monta voimallista, ei myös monta suuresta suvusta,","Te näette, rakkaat veljet, teidän kutsumisenne, ettei monta lihallista viisasta, ei monta voimallista, ei myös monta suuresta suvusta,"],[1,27,"Vaan ne, jotka maailman edessä hullut ovat, on Jumala valinnut, että hän viisaat häpiään saattais; ja ne, jotka heikot ovat maailman edessä, on Jumala valinnut, että hän väkevät häpiään saattais;","Vaan ne, jotka maailman edessä hullut ovat, on Jumala valinnut, että hän viisaat häpiään saattais; ja ne, jotka heikot ovat maailman edessä, on Jumala valinnut, että hän väkevät häpiään saattais;"],[1,28,"Ja ne alimmaisesta suvusta ja ylönkatsotut maailmassa on Jumala valinnut, ja ne, jotka ei mitään ole, että hän ne, jotka jotakin ovat, turhaksi tekis;","Ja ne alimmaisesta suvusta ja ylönkatsotut maailmassa on Jumala valinnut, ja ne, jotka ei mitään ole, että hän ne, jotka jotakin ovat, turhaksi tekis;"],[1,29,"Ettei hänen edessänsä yksikään liha kerskaisi.","Ettei hänen edessänsä yksikään liha kerskaisi."],[1,30,"Mutta te olette hänestä Kristuksessa Jesuksessa, joka meille on Jumalalta tehty viisaudeksi, ja vanhurskaudeksi, ja pyhitykseksi ja lunastukseksi:","Mutta te olette hänestä Kristuksessa Jesuksessa, joka meille on Jumalalta tehty viisaudeksi, ja vanhurskaudeksi, ja pyhitykseksi ja lunastukseksi:"],[1,31,"Että niinkuin kirjoitettu on: joka itsiänsä kerskaa, hän kerskatkaan itsiänsä Herrassa.","Että niinkuin kirjoitettu on: joka itsiänsä kerskaa, hän kerskatkaan itsiänsä Herrassa."],[2,1,"Ja, rakkaat veljet, kuin minä teidän tykönne tulin, en minä tullut korkeilla sanoilla enkä syvällä viisaudella ilmoittamaan teille Jumalan todistusta.","Ja, rakkaat veljet, kuin minä teidän tykönne tulin, en minä tullut korkeilla sanoilla enkä syvällä viisaudella ilmoittamaan teille Jumalan todistusta."],[2,2,"Sillä en minä itsiäni pitänyt teidän seassanne mitäkään tietämäni, vaan ainoasti Jesuksen Kristuksen ja sen ristiinnaulitun.","Sillä en minä itsiäni pitänyt teidän seassanne mitäkään tietämäni, vaan ainoasti Jesuksen Kristuksen ja sen ristiinnaulitun."],[2,3,"Ja minä olin teidän kanssanne heikkoudessa, ja pelvossa, ja suuressa vapistuksessa.","Ja minä olin teidän kanssanne heikkoudessa, ja pelvossa, ja suuressa vapistuksessa."],[2,4,"Ja minun puheeni ja saarnani ei ollut kaunistetuissa sanoissa ihmisten viisauden jälkeen, mutta hengen ja voiman osoituksessa,","Ja minun puheeni ja saarnani ei ollut kaunistetuissa sanoissa ihmisten viisauden jälkeen, mutta hengen ja voiman osoituksessa,"],[2,5,"Ettei teidän uskonne olisi ihmisten viisaudessa, vaan Jumalan voimassa.","Ettei teidän uskonne olisi ihmisten viisaudessa, vaan Jumalan voimassa."],[2,6,"Mutta me puhumme siitä viisaudesta, joka on täydellisten tykönä, ei tämän maailman viisaudesta, eikä tämän maailman päämiesten, jotka hukkuvat.","Mutta me puhumme siitä viisaudesta, joka on täydellisten tykönä, ei tämän maailman viisaudesta, eikä tämän maailman päämiesten, jotka hukkuvat."],[2,7,"Vaan me puhumme siitä salatusta Jumalan viisaudesta, jonka Jumala on ennen maailman alkua säätänyt meidän kunniaksemme,","Vaan me puhumme siitä salatusta Jumalan viisaudesta, jonka Jumala on ennen maailman alkua säätänyt meidän kunniaksemme,"],[2,8,"Jota ei yksikään tämän maailman päämiehistä tuntenut; sillä jos he olisivat tunteneet, niin ei he olisi kunnian Herraa ristiinnaulinneet.","Jota ei yksikään tämän maailman päämiehistä tuntenut; sillä jos he olisivat tunteneet, niin ei he olisi kunnian Herraa ristiinnaulinneet."],[2,9,"Vaan niinkuin kirjoitettu on: joita ei silmä ole nähnyt, eikä korva ole kuullut, ja ei ihmisen sydämeen ole astunut, joita Jumala on niille valmistanut, jotka häntä rakastavat.","Vaan niinkuin kirjoitettu on: joita ei silmä ole nähnyt, eikä korva ole kuullut, ja ei ihmisen sydämeen ole astunut, joita Jumala on niille valmistanut, jotka häntä rakastavat."],[2,10,"Mutta meille on Jumala sen ilmoittanut Henkensä kautta; sillä Henki kaikki tutkistelee, Jumalan syvyydetkin.","Mutta meille on Jumala sen ilmoittanut Henkensä kautta; sillä Henki kaikki tutkistelee, Jumalan syvyydetkin."],[2,11,"Sillä kuka ihminen tietää, mitä ihmisessä on, vaan ihmisen henki, joka hänessä on? Niin myös ei yksikään tiedä, mitä Jumalassa on, vaan Jumalan Henki.","Sillä kuka ihminen tietää, mitä ihmisessä on, vaan ihmisen henki, joka hänessä on? Niin myös ei yksikään tiedä, mitä Jumalassa on, vaan Jumalan Henki."],[2,12,"Mutta emme ole saaneet tämän maailman henkeä, vaan sen Hengen, joka Jumalasta on, että me tietäisimme, mitä meille Jumalalta annettu on,","Mutta emme ole saaneet tämän maailman henkeä, vaan sen Hengen, joka Jumalasta on, että me tietäisimme, mitä meille Jumalalta annettu on,"],[2,13,"Jota me myös puhumme, ei niillä sanoilla, joita inhimillinen viisaus opettaa, vaan niillä, joita Pyhä Henki opettaa, ja me tuomitsemme hengelliset asiat hengellisesti.","Jota me myös puhumme, ei niillä sanoilla, joita inhimillinen viisaus opettaa, vaan niillä, joita Pyhä Henki opettaa, ja me tuomitsemme hengelliset asiat hengellisesti."],[2,14,"Mutta ei luonnollinen ihminen ymmärrä niitä, mitkä Jumalan Hengen ovat; sillä ne ovat hänelle hulluus, ja ei taida käsittää, sillä ne hengellisesti tuomitaan.","Mutta ei luonnollinen ihminen ymmärrä niitä, mitkä Jumalan Hengen ovat; sillä ne ovat hänelle hulluus, ja ei taida käsittää, sillä ne hengellisesti tuomitaan."],[2,15,"Mutta hengellinen tuomitsee tosin kaikkia, vaan ei hän keltäkään tuomita.","Mutta hengellinen tuomitsee tosin kaikkia, vaan ei hän keltäkään tuomita."],[2,16,"Sillä kuka on tietänyt Herran mielen, joka tahtoo hänelle neuvoa antaa? Mutta meillä on Kristuksen mieli.","Sillä kuka on tietänyt Herran mielen, joka tahtoo hänelle neuvoa antaa? Mutta meillä on Kristuksen mieli."],[3,1,"Ja, rakkaat veljet! en minä taitanut teille puhua niinkuin hengellisille, vaan niinkuin lihallisille, niinkuin lapsille Kristuksessa.","Ja, rakkaat veljet! en minä taitanut teille puhua niinkuin hengellisille, vaan niinkuin lihallisille, niinkuin lapsille Kristuksessa."],[3,2,"Rieskaa minä olen teille juoda antanut, ja en ruokaa; sillä ette sitä vielä voineet, ja ette vielä nytkään voi.","Rieskaa minä olen teille juoda antanut, ja en ruokaa; sillä ette sitä vielä voineet, ja ette vielä nytkään voi."],[3,3,"Sillä te olette vielä lihalliset, sillä niinkauvan kuin teidän seassanne kateus ja riita ja eripuraisuus on, ettekö te ole lihalliset ja vaella ihmisten tavan jälkeen?","Sillä te olette vielä lihalliset, sillä niinkauvan kuin teidän seassanne kateus ja riita ja eripuraisuus on, ettekö te ole lihalliset ja vaella ihmisten tavan jälkeen?"],[3,4,"Sillä koska joku sanoo: minä olen Paavalin, ja toinen: minä Apollon: ettekö te siis ole lihalliset?","Sillä koska joku sanoo: minä olen Paavalin, ja toinen: minä Apollon: ettekö te siis ole lihalliset?"],[3,5,"Mitäs Paavali on ja mikä Apollo muuta kuin palveliat, joiden kautta te olette uskoneet, ja niinkuin Jumala kullekin antanut on?","Mitäs Paavali on ja mikä Apollo muuta kuin palveliat, joiden kautta te olette uskoneet, ja niinkuin Jumala kullekin antanut on?"],[3,6,"Minä olen istuttanut, Apollo on kastanut mutta Jumala on kasvun antanut.","Minä olen istuttanut, Apollo on kastanut mutta Jumala on kasvun antanut."],[3,7,"Niin ei se mitään ole, joka istuttaa, eikä se, joka kastaa, vaan Jumala, joka kasvun on antaa.","Niin ei se mitään ole, joka istuttaa, eikä se, joka kastaa, vaan Jumala, joka kasvun on antaa."],[3,8,"Mutta se, joka istuttaa, ja se, joka kastaa, ovat yhtä: kumpikin saa palkkansa työnsä jälkeen.","Mutta se, joka istuttaa, ja se, joka kastaa, ovat yhtä: kumpikin saa palkkansa työnsä jälkeen."],[3,9,"Sillä me olemme Jumalan apulaiset: te olette Jumalan pelto ja Jumalan rakennus.","Sillä me olemme Jumalan apulaiset: te olette Jumalan pelto ja Jumalan rakennus."],[3,10,"Sen Jumalan armon jälkeen, joka minulle annettu on, olen minä perustuksen laskenut, niinkuin taitava rakentaja, vaan toinen sen päälle rakentaa; mutta katsokaan jokainen, kuinka hän sen päälle rakentaa.","Sen Jumalan armon jälkeen, joka minulle annettu on, olen minä perustuksen laskenut, niinkuin taitava rakentaja, vaan toinen sen päälle rakentaa; mutta katsokaan jokainen, kuinka hän sen päälle rakentaa."],[3,11,"Sillä muuta perustusta, ei taida yksikään panna, vaan sen, joka pantu on, joka on Jesus Kristus.","Sillä muuta perustusta, ei taida yksikään panna, vaan sen, joka pantu on, joka on Jesus Kristus."],[3,12,"Jos nyt joku rakentaa tämän perustuksen päälle kultaa, hopiaa, kalliita kiviä, puita, heiniä, olkia:","Jos nyt joku rakentaa tämän perustuksen päälle kultaa, hopiaa, kalliita kiviä, puita, heiniä, olkia:"],[3,13,"Jokainen teko tulee julkiseksi; sillä se päivä sen on selittävä, joka tulessa ilmaantuu: ja minkäkaltainen kunkin teko on, sen tuli koettelee.","Jokainen teko tulee julkiseksi; sillä se päivä sen on selittävä, joka tulessa ilmaantuu: ja minkäkaltainen kunkin teko on, sen tuli koettelee."],[3,14,"Jos jonkun teko pysyy, jonka hän sen päälle rakentanut on, niin hän saa palkan:","Jos jonkun teko pysyy, jonka hän sen päälle rakentanut on, niin hän saa palkan:"],[3,15,"Jos jonkun teko palaa, niin hän saa vahingon; mutta hän tulee itse autuaaksi, kuitenkin niinkuin tulen kautta.","Jos jonkun teko palaa, niin hän saa vahingon; mutta hän tulee itse autuaaksi, kuitenkin niinkuin tulen kautta."],[3,16,"Ettekö te tiedä teitänne Jumalan templiksi, ja että Jumalan Henki asuu teissä?","Ettekö te tiedä teitänne Jumalan templiksi, ja että Jumalan Henki asuu teissä?"],[3,17,"Jos joku Jumalan templin turmelee, sen Jumala turmelee; sillä Jumalan templi on pyhä, niinkuin tekin olette.","Jos joku Jumalan templin turmelee, sen Jumala turmelee; sillä Jumalan templi on pyhä, niinkuin tekin olette."],[3,18,"Älkään kenkään itseänsä pettäkö: jos joku teistä luulee itsensä viisaaksi tässä maailmassa, se tulkoon tyhmäksi, että hän viisaaksi tulis.","Älkään kenkään itseänsä pettäkö: jos joku teistä luulee itsensä viisaaksi tässä maailmassa, se tulkoon tyhmäksi, että hän viisaaksi tulis."],[3,19,"Sillä tämän maailman viisaus on hulluus Jumalan tykönä. Sillä kirjoitettu on: hän käsittää taitavat heidän kavaluudessansa,","Sillä tämän maailman viisaus on hulluus Jumalan tykönä. Sillä kirjoitettu on: hän käsittää taitavat heidän kavaluudessansa,"],[3,20,"Ja taas: Herra tietää viisasten ajatukset, että ne turhat ovat.","Ja taas: Herra tietää viisasten ajatukset, että ne turhat ovat."],[3,21,"Sentähden älkään yksikään ihmisistä kerskatko; sillä kaikki ovat teidän omanne:","Sentähden älkään yksikään ihmisistä kerskatko; sillä kaikki ovat teidän omanne:"],[3,22,"Joko se olis Paavali eli Apollo, eli Kephas, taikka maailma, eli elämä, eli kuolema, taikka nykyiset eli tulevaiset: kaikki ovat teidän,","Joko se olis Paavali eli Apollo, eli Kephas, taikka maailma, eli elämä, eli kuolema, taikka nykyiset eli tulevaiset: kaikki ovat teidän,"],[3,23,"Mutta te olette Kristuksen, vaan Kristus on Jumalan.","Mutta te olette Kristuksen, vaan Kristus on Jumalan."],[4,1,"Jokainen pitäköön meitä Kristuksen palvelioina ja Jumalan salaisuutten huoneenhaltioina.","Jokainen pitäköön meitä Kristuksen palvelioina ja Jumalan salaisuutten huoneenhaltioina."],[4,2,"Mutta ainoastaan se huoneenhaltiain seassa etsitään, että joku uskolliseksi löydettäisiin.","Mutta ainoastaan se huoneenhaltiain seassa etsitään, että joku uskolliseksi löydettäisiin."],[4,3,"Mutta vähän minä sitä tottelen, että minä teiltä tuomitaan eli inhimilliseltä päivältä: ja en minä itsekään tuomitse minuani;","Mutta vähän minä sitä tottelen, että minä teiltä tuomitaan eli inhimilliseltä päivältä: ja en minä itsekään tuomitse minuani;"],[4,4,"Sillä en minä tiedä mitään kanssani; mutta en minä sentähden vanhurskautettu ole, vaan Herra on se, joka minun tuomitsee.","Sillä en minä tiedä mitään kanssani; mutta en minä sentähden vanhurskautettu ole, vaan Herra on se, joka minun tuomitsee."],[4,5,"Sentähden älkäät tuomitko ennen aikaa, siihenasti kuin Herra tulee, joka nekin valkeuteen saattaa, mitkä pimeydessä peitetyt ovat, ja ilmoittaa sydänten aivoitukset: ja silloin kukin saa kunnian Jumalalta.","Sentähden älkäät tuomitko ennen aikaa, siihenasti kuin Herra tulee, joka nekin valkeuteen saattaa, mitkä pimeydessä peitetyt ovat, ja ilmoittaa sydänten aivoitukset: ja silloin kukin saa kunnian Jumalalta."],[4,6,"Mutta näitä, rakkaat veljet, olen minä minustani ja Apollosta ulostoimittanut teidän tähtenne, että te meistä oppisitte, ettei kenkään enempää itsestänsä ajattelisi kuin kirjoitettu on, ettei yksikään teistä toistansa vastaan pidä jonkun tähden itsiänsä paisuttaman.","Mutta näitä, rakkaat veljet, olen minä minustani ja Apollosta ulostoimittanut teidän tähtenne, että te meistä oppisitte, ettei kenkään enempää itsestänsä ajattelisi kuin kirjoitettu on, ettei yksikään teistä toistansa vastaan pidä jonkun tähden itsiänsä paisuttaman."],[4,7,"Sillä kuka sinun eroittaa? Taikka mitä sinulla on, jota et sinä ole saanut? Jos siitä siis saanut olet, mitäs kerskaat niinkuin et sinä saanut olisi?","Sillä kuka sinun eroittaa? Taikka mitä sinulla on, jota et sinä ole saanut? Jos siitä siis saanut olet, mitäs kerskaat niinkuin et sinä saanut olisi?"],[4,8,"Jo te olette ravitut, jo te olette rikastuneet, ilman meitä te vallitsette: ja oi jospa te tosin vallitsisitte, että mekin teidän kanssanne vallitsisimme!","Jo te olette ravitut, jo te olette rikastuneet, ilman meitä te vallitsette: ja oi jospa te tosin vallitsisitte, että mekin teidän kanssanne vallitsisimme!"],[4,9,"Sillä minä luulen, että Jumala on meitä apostoleita viimeisiksi asettanut, niinkuin surmattaviksi; sillä me olemme maailmalle, ja enkeleille, ja ihmisille ihmeeksi tulleet.","Sillä minä luulen, että Jumala on meitä apostoleita viimeisiksi asettanut, niinkuin surmattaviksi; sillä me olemme maailmalle, ja enkeleille, ja ihmisille ihmeeksi tulleet."],[4,10,"Me olemme tomppelit Kristuksen tähden, mutta te toimelliset Kristuksessa: me heikot, mutta te väkevät: te kunnialliset, mutta me katsotut ylön.","Me olemme tomppelit Kristuksen tähden, mutta te toimelliset Kristuksessa: me heikot, mutta te väkevät: te kunnialliset, mutta me katsotut ylön."],[4,11,"Hamaan tähän hetkeen asti kärsimme me nälkää ja janoa, ja olemme alasti, ja meitä lyödään korvalle ja ei meillä ole vahvaa asuinsiaa:","Hamaan tähän hetkeen asti kärsimme me nälkää ja janoa, ja olemme alasti, ja meitä lyödään korvalle ja ei meillä ole vahvaa asuinsiaa:"],[4,12,"Ja me näemme vaivaa, työtä tehden omilla käsillämme. Kuin meitä soimataan, niin me hyvästi lausumme: kuin meitä vainotaan, niin me kärsimme.","Ja me näemme vaivaa, työtä tehden omilla käsillämme. Kuin meitä soimataan, niin me hyvästi lausumme: kuin meitä vainotaan, niin me kärsimme."],[4,13,"Kuin meitä pilkataan, niin me rukoilemme: me olemme tulleet niinkuin maailman tunkioksi ja kaikkein saastaisuudeksi tähän päivään asti.","Kuin meitä pilkataan, niin me rukoilemme: me olemme tulleet niinkuin maailman tunkioksi ja kaikkein saastaisuudeksi tähän päivään asti."],[4,14,"En minä näitä kirjoita häväistäkseni teitä, vaan minä neuvon teitä niinkuin rakkaita lapsiani.","En minä näitä kirjoita häväistäkseni teitä, vaan minä neuvon teitä niinkuin rakkaita lapsiani."],[4,15,"Sillä ehkä teillä olis kymmenentuhatta opettajaa Kristuksessa, niin ei teillä kuitenkaan ole monta isää; sillä minä olen teitä Kristuksessa Jesuksessa siittänyt evankeliumin kautta.","Sillä ehkä teillä olis kymmenentuhatta opettajaa Kristuksessa, niin ei teillä kuitenkaan ole monta isää; sillä minä olen teitä Kristuksessa Jesuksessa siittänyt evankeliumin kautta."],[4,16,"Sentähden neuvon minä teitä, olkaat minun tavoittajani.","Sentähden neuvon minä teitä, olkaat minun tavoittajani."],[4,17,"Sentähden lähetin minä teille Timoteuksen, joka on minun rakas ja uskollinen poikani Herrassa, jonka pitää muistuttaman teille minun tieni, jotka ovat Kristuksessa, niinkuin minä joka paikassa kaikissa seurakunnissa opetan.","Sentähden lähetin minä teille Timoteuksen, joka on minun rakas ja uskollinen poikani Herrassa, jonka pitää muistuttaman teille minun tieni, jotka ovat Kristuksessa, niinkuin minä joka paikassa kaikissa seurakunnissa opetan."],[4,18,"Mutta muutamat ovat teistä paisuneet, niinkuin en minä teidän tykönne tuleva oliskaan.","Mutta muutamat ovat teistä paisuneet, niinkuin en minä teidän tykönne tuleva oliskaan."],[4,19,"Mutta ennen paljoa aikaa tulen minä teidän tykönne, jos Herra tahtoo, ja tahdon tietää, ei paisuneitten sanojen, vaan voimaa.","Mutta ennen paljoa aikaa tulen minä teidän tykönne, jos Herra tahtoo, ja tahdon tietää, ei paisuneitten sanojen, vaan voimaa."],[4,20,"Sillä Jumalan valtakunta ei ole puheessa, vaan voimassa.","Sillä Jumalan valtakunta ei ole puheessa, vaan voimassa."],[4,21,"Kumman te tahdotte: että minä tulen vitsalla teidän tykönne, taikka rakkaudella ja hengen siveydellä?","Kumman te tahdotte: että minä tulen vitsalla teidän tykönne, taikka rakkaudella ja hengen siveydellä?"],[5,1,"Täydellisesti kuuluu teidän seassanne huoruus, ja senkaltainen huoruus, josta ei pakanatkaan sanoa tiedä, niin että joku isänsä emäntää pitää.","Täydellisesti kuuluu teidän seassanne huoruus, ja senkaltainen huoruus, josta ei pakanatkaan sanoa tiedä, niin että joku isänsä emäntää pitää."],[5,2,"Ja te olette paisuneet, ja miksi ette enemmin murehtineet, että se, joka senkaltaisen työn tehnyt on, teidän seastanne otettaisiin pois.","Ja te olette paisuneet, ja miksi ette enemmin murehtineet, että se, joka senkaltaisen työn tehnyt on, teidän seastanne otettaisiin pois."],[5,3,"Mutta minä tosin, joka niinkuin ruumiin puolesta poissa ollen, kuitenkin hengessä tykönä ollen, olen jo niinkuin tykönä oleva sen tuominnut, että hän, joka sen niin tehnyt on,","Mutta minä tosin, joka niinkuin ruumiin puolesta poissa ollen, kuitenkin hengessä tykönä ollen, olen jo niinkuin tykönä oleva sen tuominnut, että hän, joka sen niin tehnyt on,"],[5,4,"Meidän Herran Jesuksen Kristuksen nimeen, teidän kokoontulemisessanne, ynnä minun henkeni kanssa, meidän Herran Jesuksen Kristuksen voimalla,","Meidän Herran Jesuksen Kristuksen nimeen, teidän kokoontulemisessanne, ynnä minun henkeni kanssa, meidän Herran Jesuksen Kristuksen voimalla,"],[5,5,"Annetaan saatanan haltuun lihan kadotukseksi, että henki autuaaksi tulis Herran Jesuksen päivänä.","Annetaan saatanan haltuun lihan kadotukseksi, että henki autuaaksi tulis Herran Jesuksen päivänä."],[5,6,"Ei ole teidän kerskauksenne hyvä: ettekö te tiedä, että vähä hapatus kaiken taikinan hapattaa?","Ei ole teidän kerskauksenne hyvä: ettekö te tiedä, että vähä hapatus kaiken taikinan hapattaa?"],[5,7,"Sentähden peratkaat se vanha taikina, että te olisitte uusi taikina, niinkuin te happamattomat olette; sillä meidän pääsiäislampaamme on meidän edestämme uhrattu, joka on Kristus.","Sentähden peratkaat se vanha taikina, että te olisitte uusi taikina, niinkuin te happamattomat olette; sillä meidän pääsiäislampaamme on meidän edestämme uhrattu, joka on Kristus."],[5,8,"Sentähden pitäkäämme juhlaa, ei vanhassa hapatuksessa, eikä pahuuden ja vääryyden hapatuksessa, vaan vakuuden ja totuuden happamattomassa taikinassa.","Sentähden pitäkäämme juhlaa, ei vanhassa hapatuksessa, eikä pahuuden ja vääryyden hapatuksessa, vaan vakuuden ja totuuden happamattomassa taikinassa."],[5,9,"Minä olen teille lähetyskirjassa kirjoittanut, ettei teidän pitäisi sekaantuman huorintekiäin kanssa.","Minä olen teille lähetyskirjassa kirjoittanut, ettei teidän pitäisi sekaantuman huorintekiäin kanssa."],[5,10,"Ja ei kaiketi tämän maailman huorintekiäin kanssa, eli ahneitten, eli raateliain, eli epäjumalain palveliain; sillä niin tulis teidän maailmasta paeta pois.","Ja ei kaiketi tämän maailman huorintekiäin kanssa, eli ahneitten, eli raateliain, eli epäjumalain palveliain; sillä niin tulis teidän maailmasta paeta pois."],[5,11,"Mutta nyt minä olen kirjoittanut, ettei teidän pidä heihin sekaantuman, jos joku, joka veljeksi kutsutaan, olis huorintekiä, taikka ahne, eli epäjumalain palvelia, taikka pilkkaaja, eli juomari, taikka raatelia; älkäät senkaltaisen kanssa syökö;","Mutta nyt minä olen kirjoittanut, ettei teidän pidä heihin sekaantuman, jos joku, joka veljeksi kutsutaan, olis huorintekiä, taikka ahne, eli epäjumalain palvelia, taikka pilkkaaja, eli juomari, taikka raatelia; älkäät senkaltaisen kanssa syökö;"],[5,12,"Sillä mitä minun tulee tuomita niitä, jotka ulkona ovat? Ettekö te niitä tuomitse, jotka sisällä ovat?","Sillä mitä minun tulee tuomita niitä, jotka ulkona ovat? Ettekö te niitä tuomitse, jotka sisällä ovat?"],[5,13,"Mutta Jumala ne tuomitsee, jotka ulkona ovat. Ajakaat itsekin paha pois tyköänne.","Mutta Jumala ne tuomitsee, jotka ulkona ovat. Ajakaat itsekin paha pois tyköänne."],[6,1,"Miksi joku teistä, jolla on toisen kanssa jotakin asiaa, rohkenee riidellä vääräin ja ei pyhäin edestä?","Miksi joku teistä, jolla on toisen kanssa jotakin asiaa, rohkenee riidellä vääräin ja ei pyhäin edestä?"],[6,2,"Ettekö te tiedä, että pyhät pitää maailmaa tuomitseman? Ja jos maailma pitää teidän kauttanne tuomittaman, ettekö siis te kelpaa pienempiä asioita tuomitsemaan?","Ettekö te tiedä, että pyhät pitää maailmaa tuomitseman? Ja jos maailma pitää teidän kauttanne tuomittaman, ettekö siis te kelpaa pienempiä asioita tuomitsemaan?"],[6,3,"Ettekö te tiedä, että meidän pitää enkeleitäkin tuomitseman? kuinka siis ei ajallisia asioita?","Ettekö te tiedä, että meidän pitää enkeleitäkin tuomitseman? kuinka siis ei ajallisia asioita?"],[6,4,"Kuin siis teillä on jotakuta asiaa ajallisesta hyvyydestä, niin te otatte ne, jotka seurakunnassa ovat katsotut ylön, ja asetatte tuomariksi.","Kuin siis teillä on jotakuta asiaa ajallisesta hyvyydestä, niin te otatte ne, jotka seurakunnassa ovat katsotut ylön, ja asetatte tuomariksi."],[6,5,"Teille minä sanon näitä häpiäksi: eikö niin yhtään viisasta ole teidän seassanne, joka taitais tuomita veljiensä välillä?","Teille minä sanon näitä häpiäksi: eikö niin yhtään viisasta ole teidän seassanne, joka taitais tuomita veljiensä välillä?"],[6,6,"Vaan veli riitelee veljensä kanssa, ja sittenkin uskottoman edessä.","Vaan veli riitelee veljensä kanssa, ja sittenkin uskottoman edessä."],[6,7,"Niin on siis kaiketi vika teidän seassanne, että te toinen toisenne kanssa käytte oikeuden eteen. Miksi ette paremmin vääryyttä kärsi? miksi ette ennen suo teitänne vahingoittaa?","Niin on siis kaiketi vika teidän seassanne, että te toinen toisenne kanssa käytte oikeuden eteen. Miksi ette paremmin vääryyttä kärsi? miksi ette ennen suo teitänne vahingoittaa?"],[6,8,"Vaan te itse vääryyden ja vahingon teette, ja semminkin teidän veljillenne.","Vaan te itse vääryyden ja vahingon teette, ja semminkin teidän veljillenne."],[6,9,"Ettekö te tiedä, ettei väärät pidä Jumalan valtakuntaa perimän? Älkäät eksykö; ei huorintekiäin, eikä epäjumalten palvelijain, eikä salavuoteisten, eikä pehmiäin, eikä miesten kanssa makaajain,","Ettekö te tiedä, ettei väärät pidä Jumalan valtakuntaa perimän? Älkäät eksykö; ei huorintekiäin, eikä epäjumalten palvelijain, eikä salavuoteisten, eikä pehmiäin, eikä miesten kanssa makaajain,"],[6,10,"Eikä varasten, eikä ahnetten, eikä juomarien, eikä pilkkaajain eikä raateliain pidä Jumalan valtakuntaa perimän.","Eikä varasten, eikä ahnetten, eikä juomarien, eikä pilkkaajain eikä raateliain pidä Jumalan valtakuntaa perimän."],[6,11,"Ja senkaltaiset te muutamat olitte; mutta te olette pestyt, te olette pyhitetyt, te olette vanhurskaaksi tulleet Herran Jesuksen nimen kautta ja meidän Jumalamme hengen kautta.","Ja senkaltaiset te muutamat olitte; mutta te olette pestyt, te olette pyhitetyt, te olette vanhurskaaksi tulleet Herran Jesuksen nimen kautta ja meidän Jumalamme hengen kautta."],[6,12,"Kaikissa on minulla valta, vaan ei kaikki ole hyväksi: kaikissa on minulla valta, mutta en minä kenenkään alamainen ole.","Kaikissa on minulla valta, vaan ei kaikki ole hyväksi: kaikissa on minulla valta, mutta en minä kenenkään alamainen ole."],[6,13,"Ruoka on vatsalle säätty ja vatsa rualle; mutta Jumala on tämän ja sen hukuttava. Ei ruumis ole säätty huoruuteen, vaan Herralle, ja Herra ruumiille.","Ruoka on vatsalle säätty ja vatsa rualle; mutta Jumala on tämän ja sen hukuttava. Ei ruumis ole säätty huoruuteen, vaan Herralle, ja Herra ruumiille."],[6,14,"Mutta Jumala on Herran herättänyt, niin hän on myös meitäkin voimallansa herättävä.","Mutta Jumala on Herran herättänyt, niin hän on myös meitäkin voimallansa herättävä."],[6,15,"Ettekö te tiedä, että teidän ruumiinne ovat Kristuksen jäsenet? Pitäiskö siis minun Kristuksen jäsenet ottaman ja porton jäseniksi tekemän? Pois se!","Ettekö te tiedä, että teidän ruumiinne ovat Kristuksen jäsenet? Pitäiskö siis minun Kristuksen jäsenet ottaman ja porton jäseniksi tekemän? Pois se!"],[6,16,"Taikka ettekö te tiedä, että se, joka porttoon ryhtyy, hän on yksi ruumis sen kanssa? Sillä he tulevat, sanoo hän, kaksi yhdeksi lihaksi.","Taikka ettekö te tiedä, että se, joka porttoon ryhtyy, hän on yksi ruumis sen kanssa? Sillä he tulevat, sanoo hän, kaksi yhdeksi lihaksi."],[6,17,"Mutta joka Herraan ryhtyy, se on yksi henki hänen kanssansa.","Mutta joka Herraan ryhtyy, se on yksi henki hänen kanssansa."],[6,18,"Välttäkäät huoruutta. Kaikki synnit, joita ihminen tekee, ovat ulkona ruumiista; vaan joka huorin tekee, tekee syntiä omassa ruumiissansa.","Välttäkäät huoruutta. Kaikki synnit, joita ihminen tekee, ovat ulkona ruumiista; vaan joka huorin tekee, tekee syntiä omassa ruumiissansa."],[6,19,"Vai ettekö te tiedä, että teidän ruumiinne on Pyhän Hengen templi, joka teissä on, jonka te Jumalalta saitte, ja ettepä te ole teidän omanne?","Vai ettekö te tiedä, että teidän ruumiinne on Pyhän Hengen templi, joka teissä on, jonka te Jumalalta saitte, ja ettepä te ole teidän omanne?"],[6,20,"Sillä te olette kalliisti ostetut; kunnioittakaat siis Jumalaa teidän ruumiissanne ja teidän hengessänne, jotka Jumalan ovat.","Sillä te olette kalliisti ostetut; kunnioittakaat siis Jumalaa teidän ruumiissanne ja teidän hengessänne, jotka Jumalan ovat."],[7,1,"Mutta niistä, joita te minulle kirjoititte, hyvä on miehelle, ettei hän vaimoon ryhdy.","Mutta niistä, joita te minulle kirjoititte, hyvä on miehelle, ettei hän vaimoon ryhdy."],[7,2,"Mutta huoruuden tähden pitäköön kukin oman vaimonsa, ja jokainen pitäköön oman miehensä.","Mutta huoruuden tähden pitäköön kukin oman vaimonsa, ja jokainen pitäköön oman miehensä."],[7,3,"Mies antakoon vaimolle velvollisen mielisuosion, niin myös vaimo miehelle.","Mies antakoon vaimolle velvollisen mielisuosion, niin myös vaimo miehelle."],[7,4,"Ei ole vaimolla valtaa omalle ruumiillensa, vaan miehellä: ei myös miehellä ole valtaa ruumiillensa, vaan vaimolla.","Ei ole vaimolla valtaa omalle ruumiillensa, vaan miehellä: ei myös miehellä ole valtaa ruumiillensa, vaan vaimolla."],[7,5,"Älkäät toinen toistanne vältkö, jollei se ole molempain suosiosta hetkeksi, että teillä jouto olis paastota ja rukoilla: ja tulkaat jälleen yhteen, ettei saatana teitä kiusaisi teidän himonne hillimättömyyden puolesta.","Älkäät toinen toistanne vältkö, jollei se ole molempain suosiosta hetkeksi, että teillä jouto olis paastota ja rukoilla: ja tulkaat jälleen yhteen, ettei saatana teitä kiusaisi teidän himonne hillimättömyyden puolesta."],[7,6,"Mutta sen sanon minä teille suomisen ja ei käskyn jälkeen.","Mutta sen sanon minä teille suomisen ja ei käskyn jälkeen."],[7,7,"Sillä minä tahtoisin, että kaikki ihmiset niin olisivat kuin minäkin olen; mutta jokaisella on oma lahja Jumalalta, yhdellä niin ja toisella näin.","Sillä minä tahtoisin, että kaikki ihmiset niin olisivat kuin minäkin olen; mutta jokaisella on oma lahja Jumalalta, yhdellä niin ja toisella näin."],[7,8,"Vaan minä sanon naimattomille ja leskille: se on heille hyvä, jos he ovat niinkuin minäkin.","Vaan minä sanon naimattomille ja leskille: se on heille hyvä, jos he ovat niinkuin minäkin."],[7,9,"Vaan ellei he voi itsiänsä pidättää, niin naikaan; sillä parempi on naida kuin palaa.","Vaan ellei he voi itsiänsä pidättää, niin naikaan; sillä parempi on naida kuin palaa."],[7,10,"Mutta naineelle käsken, en minä, vaan Herra, ettei vaimon pidä miehestänsä eriämän.","Mutta naineelle käsken, en minä, vaan Herra, ettei vaimon pidä miehestänsä eriämän."],[7,11,"Mutta jos hän eriää, niin olkoon naimatta taikka sopikaan miehensä kanssa, ja älköön mies hyljätkö vaimoansa.","Mutta jos hän eriää, niin olkoon naimatta taikka sopikaan miehensä kanssa, ja älköön mies hyljätkö vaimoansa."],[7,12,"Vaan muille sanon minä ja ei Herra: jos jollakin veljellä on uskotoin vaimo, ja se mielistyy hänen kanssansa asumaan, älköön sitä itsestänsä eroittako.","Vaan muille sanon minä ja ei Herra: jos jollakin veljellä on uskotoin vaimo, ja se mielistyy hänen kanssansa asumaan, älköön sitä itsestänsä eroittako."],[7,13,"Ja jos jollakin vaimolla on uskotoin mies, ja hän tahtoo sen kanssa asua, älköön häntä itsestänsä eroittako.","Ja jos jollakin vaimolla on uskotoin mies, ja hän tahtoo sen kanssa asua, älköön häntä itsestänsä eroittako."],[7,14,"Sillä uskotoin mies on vaimonsa kautta pyhitetty, ja uskotoin vaimo on pyhitetty miehensä kautta: Muutoin olisivat teidän lapsenne saastaiset, vaan nyt ne ovat pyhitetyt.","Sillä uskotoin mies on vaimonsa kautta pyhitetty, ja uskotoin vaimo on pyhitetty miehensä kautta: Muutoin olisivat teidän lapsenne saastaiset, vaan nyt ne ovat pyhitetyt."],[7,15,"Mutta jos uskotoin itsensä eroittaa, niin olkoot eroitetut. Eipä veli taikka sisar ole sidottu orjuuteen senmuotoisissa menoissa; mutta rauhassa on Jumala meitä kutsunut.","Mutta jos uskotoin itsensä eroittaa, niin olkoot eroitetut. Eipä veli taikka sisar ole sidottu orjuuteen senmuotoisissa menoissa; mutta rauhassa on Jumala meitä kutsunut."],[7,16,"Sillä kuinkas tiedät, vaimo, jos sinä miehes taidat autuaaksi saattaa? Eli sinä mies, kuinkas tiedät, jos sinä taidat vaimos autuaaksi saattaa?","Sillä kuinkas tiedät, vaimo, jos sinä miehes taidat autuaaksi saattaa? Eli sinä mies, kuinkas tiedät, jos sinä taidat vaimos autuaaksi saattaa?"],[7,17,"Kuitenkin niinkuin Jumala kullekin on jakanut: jokainen niin vaeltakaan, kuin Herra on hänen kutsunut: ja niin minäkin kaikissa seurakunnissa säädän.","Kuitenkin niinkuin Jumala kullekin on jakanut: jokainen niin vaeltakaan, kuin Herra on hänen kutsunut: ja niin minäkin kaikissa seurakunnissa säädän."],[7,18,"Jos joku ympärileikattu on kutsuttu, älkään se esinahkaa pyytäkö: jos joku on esinahasta kutsuttu, älkään se antako itsiänsä ympärileikata.","Jos joku ympärileikattu on kutsuttu, älkään se esinahkaa pyytäkö: jos joku on esinahasta kutsuttu, älkään se antako itsiänsä ympärileikata."],[7,19,"Ympärileikkaus ei ole mitään, eikä esinahka mitään ole, vaan Jumalan käskyin pitämys.","Ympärileikkaus ei ole mitään, eikä esinahka mitään ole, vaan Jumalan käskyin pitämys."],[7,20,"Jokainen pysyköön siinä kutsumisessa, johonka hän kutsuttu on.","Jokainen pysyköön siinä kutsumisessa, johonka hän kutsuttu on."],[7,21,"Jos sinä olet orjaksi kutsuttu, älä sitä murehdi: kuitenkin jos sinä taidat vapaaksi tulla, niin nautitse sitä paremmin.","Jos sinä olet orjaksi kutsuttu, älä sitä murehdi: kuitenkin jos sinä taidat vapaaksi tulla, niin nautitse sitä paremmin."],[7,22,"Sillä joka orjaksi on Herrassa kutsuttu, se on Herran vapaa: niin myös joka vapaaksi on kutsuttu, hän on Kristuksen orja.","Sillä joka orjaksi on Herrassa kutsuttu, se on Herran vapaa: niin myös joka vapaaksi on kutsuttu, hän on Kristuksen orja."],[7,23,"Te olette kalliisti ostetut! älkäät ihmisten orjat olko!","Te olette kalliisti ostetut! älkäät ihmisten orjat olko!"],[7,24,"Itsekukin, rakkaat veljet, jossa hän kutsuttu on, olkaan siinä Jumalan tykönä.","Itsekukin, rakkaat veljet, jossa hän kutsuttu on, olkaan siinä Jumalan tykönä."],[7,25,"Mutta neitseistä ei ole minulla Herran käskyä; kuitenkin sanon minä minun neuvoni niinkuin laupiuden saanut Herralta uskollisena ollakseni.","Mutta neitseistä ei ole minulla Herran käskyä; kuitenkin sanon minä minun neuvoni niinkuin laupiuden saanut Herralta uskollisena ollakseni."],[7,26,"Minä luulen siis sen hyväksi, nykyisen tuskan tähden, että ihmisen on niin hyvä olla.","Minä luulen siis sen hyväksi, nykyisen tuskan tähden, että ihmisen on niin hyvä olla."],[7,27,"Jos sinä olet vaimoon sidottu, älä pyydä eroa; jos sinä olet vaimotoin, niin älä pyydä vaimoa.","Jos sinä olet vaimoon sidottu, älä pyydä eroa; jos sinä olet vaimotoin, niin älä pyydä vaimoa."],[7,28,"Mutta jos sinä myös olet nainut, et sinä syntiä tehnyt, ja jos neitsy huoli, ei hänkään syntiä tehnyt. Kuitenkin senkaltaiset saavat vaivan ruumiisensa. Mutta minä säästäisin mielelläni teitä.","Mutta jos sinä myös olet nainut, et sinä syntiä tehnyt, ja jos neitsy huoli, ei hänkään syntiä tehnyt. Kuitenkin senkaltaiset saavat vaivan ruumiisensa. Mutta minä säästäisin mielelläni teitä."],[7,29,"Mutta sen minä sanon, rakkaat veljet, aika on lyhetty. Mitä enempi? Joilla vaimot ovat, olkaan niinkuin ei heillä olisikaan,","Mutta sen minä sanon, rakkaat veljet, aika on lyhetty. Mitä enempi? Joilla vaimot ovat, olkaan niinkuin ei heillä olisikaan,"],[7,30,"Ja jotka itkevät, niinkuin ei he itkisikään: ja jotka iloitsevat, niinkuin ei iloitsisikaan: ja jotka ostavat, niinkuin ei nautitsisikaan;","Ja jotka itkevät, niinkuin ei he itkisikään: ja jotka iloitsevat, niinkuin ei iloitsisikaan: ja jotka ostavat, niinkuin ei nautitsisikaan;"],[7,31,"Ja jotka tätä maailmaa viljelevät, ettei he sitä väärin käyttäisi; sillä tämän maailman meno on menevä.","Ja jotka tätä maailmaa viljelevät, ettei he sitä väärin käyttäisi; sillä tämän maailman meno on menevä."],[7,32,"Mutta minä tahtoisin, että te ilman murhetta olisitte: naimatoin tottelee niitä, jotka Herran ovat, kuinka hänen pitää Herralle kelpaaman.","Mutta minä tahtoisin, että te ilman murhetta olisitte: naimatoin tottelee niitä, jotka Herran ovat, kuinka hänen pitää Herralle kelpaaman."],[7,33,"Mutta joka nai, hän suree maailmallisista, kuinka hän emännällensä kelpais.","Mutta joka nai, hän suree maailmallisista, kuinka hän emännällensä kelpais."],[7,34,"Nämät ovat eroitetut, vaimo ja neitsy, joka ei naitu ole, se murehtii niitä, jotka Herran ovat, että hän pyhä olis sekä ruumiilla että hengellä; mutta se, joka naitu on, murehtii maailmallisista, kuinka hänen pitää miehellensä kelpaaman.","Nämät ovat eroitetut, vaimo ja neitsy, joka ei naitu ole, se murehtii niitä, jotka Herran ovat, että hän pyhä olis sekä ruumiilla että hengellä; mutta se, joka naitu on, murehtii maailmallisista, kuinka hänen pitää miehellensä kelpaaman."],[7,35,"Mutta senkaltaista sanon minä teidän tarpeeksenne: ei, että minä paulan teidän päällenne heittäisin, vaan että te soveliaasti ja hyvin Herrassa riippuisitte, ilman eroittamatta.","Mutta senkaltaista sanon minä teidän tarpeeksenne: ei, että minä paulan teidän päällenne heittäisin, vaan että te soveliaasti ja hyvin Herrassa riippuisitte, ilman eroittamatta."],[7,36,"Mutta jos joku luulee, ettei se sovi hänen neitseellensä, sittekuin hän jo naitavissa on, eikä saa toisin olla, niin tehkään, mitä hän tahtoo, ei hän syntiä tee; sallikaan hänen huolla.","Mutta jos joku luulee, ettei se sovi hänen neitseellensä, sittekuin hän jo naitavissa on, eikä saa toisin olla, niin tehkään, mitä hän tahtoo, ei hän syntiä tee; sallikaan hänen huolla."],[7,37,"Mutta joka seisoo vahvana sydämessänsä ja ei ole vaadittu, vaan hänellä on oma ehtonsa ja päättää sen sydämessänsä, että hän tahtoo neitseensä pitää, se tekee hyvin.","Mutta joka seisoo vahvana sydämessänsä ja ei ole vaadittu, vaan hänellä on oma ehtonsa ja päättää sen sydämessänsä, että hän tahtoo neitseensä pitää, se tekee hyvin."],[7,38,"Sentähden joka naittaa, se tekee hyvin; mutta joka ei naita, hän tekee paremmin.","Sentähden joka naittaa, se tekee hyvin; mutta joka ei naita, hän tekee paremmin."],[7,39,"Vaimo on sidottu lakiin, niinkauvan kuin hänen miehensä elää; vaan kuin hänen miehensä kuollut on, niin hän on vapaa toiselle huolemaan, kelle hän tahtoo; ainoasti että se Herrassa tapahtuu.","Vaimo on sidottu lakiin, niinkauvan kuin hänen miehensä elää; vaan kuin hänen miehensä kuollut on, niin hän on vapaa toiselle huolemaan, kelle hän tahtoo; ainoasti että se Herrassa tapahtuu."],[7,40,"Vaan hän on autuaampi, minun luullakseni, jos hän sillänsä pysyy; sillä minä luulen, että minullakin on Jumalan Henki.","Vaan hän on autuaampi, minun luullakseni, jos hän sillänsä pysyy; sillä minä luulen, että minullakin on Jumalan Henki."],[8,1,"Epäjumalain uhreista me tiedämme, että kaikilla meillä on tieto. Tieto paisuttaa, mutta rakkaus rakentaa.","Epäjumalain uhreista me tiedämme, että kaikilla meillä on tieto. Tieto paisuttaa, mutta rakkaus rakentaa."],[8,2,"Mutta jos joku luulee jotakin tietävänsä, ei hän vielä mitään tiedä, kuin hänen tulis tietää.","Mutta jos joku luulee jotakin tietävänsä, ei hän vielä mitään tiedä, kuin hänen tulis tietää."],[8,3,"Mutta jos joku Jumalaa rakastaa, se on tuttu häneltä.","Mutta jos joku Jumalaa rakastaa, se on tuttu häneltä."],[8,4,"Niin me nyt tiedämme siitä ruasta, joka epäjumalille uhrataan, ettei yhtään epäjumalaa maailmassa olekaan, ja ettei yhtään muuta Jumalaa ole kuin yksi;","Niin me nyt tiedämme siitä ruasta, joka epäjumalille uhrataan, ettei yhtään epäjumalaa maailmassa olekaan, ja ettei yhtään muuta Jumalaa ole kuin yksi;"],[8,5,"Ja vaikka muutamat ovat, jotka jumaliksi kutsutaan, olkoon se taivaassa eli maan päällä, (niinkuin monta jumalaa ja monta herraa on:)","Ja vaikka muutamat ovat, jotka jumaliksi kutsutaan, olkoon se taivaassa eli maan päällä, (niinkuin monta jumalaa ja monta herraa on:)"],[8,6,"Niin on kuitenkin meillä yksi Jumala, Isä, josta kaikki ovat, ja me hänessä, ja yksi Herra Jesus Kristus, jonka kautta kaikki ovat, ja me hänen kauttansa.","Niin on kuitenkin meillä yksi Jumala, Isä, josta kaikki ovat, ja me hänessä, ja yksi Herra Jesus Kristus, jonka kautta kaikki ovat, ja me hänen kauttansa."],[8,7,"Mutta ei jokaisella ole tietoa; sillä muutamat tekevät itsellensä omantunnon epäjumalista ja syövät niinkuin epäjumalille uhrattua, ja että heidän omatuntonsa on heikko, niin se saastutetaan.","Mutta ei jokaisella ole tietoa; sillä muutamat tekevät itsellensä omantunnon epäjumalista ja syövät niinkuin epäjumalille uhrattua, ja että heidän omatuntonsa on heikko, niin se saastutetaan."],[8,8,"Mutta ei ruoka meitä saata otolliseksi Jumalan edessä; jos me syömme, emme siitä rikkaammaksi tule; ellemme taas syö, emmepä me sentähden köyhemmäksi tule.","Mutta ei ruoka meitä saata otolliseksi Jumalan edessä; jos me syömme, emme siitä rikkaammaksi tule; ellemme taas syö, emmepä me sentähden köyhemmäksi tule."],[8,9,"Vaan katsokaat, ettei tämä teidän vapautenne tulisi heikoille pahennukseksi;","Vaan katsokaat, ettei tämä teidän vapautenne tulisi heikoille pahennukseksi;"],[8,10,"Sillä jos joku näkee sinun, jolla tieto on, atrioitsevan epäjumalain huoneissa, eikö siitä omatunto, joka heikko on, yllytetä epäjumalain uhria syömään?","Sillä jos joku näkee sinun, jolla tieto on, atrioitsevan epäjumalain huoneissa, eikö siitä omatunto, joka heikko on, yllytetä epäjumalain uhria syömään?"],[8,11,"Ja niin sinun tietos kautta sinun veljes hukkaantuu, joka heikko on, jonka tähden Kristus on kuollut.","Ja niin sinun tietos kautta sinun veljes hukkaantuu, joka heikko on, jonka tähden Kristus on kuollut."],[8,12,"Mutta kuin te niin syntiä teette veljiänne vastaan ja särjette heidän heikon omantuntonsa, niin te Kristusta vastaan syntiä teette.","Mutta kuin te niin syntiä teette veljiänne vastaan ja särjette heidän heikon omantuntonsa, niin te Kristusta vastaan syntiä teette."],[8,13,"Sentähden jos ruoka minun veljeni pahentais, niin en minä ikänäni söisi lihaa, etten minä veljeäni pahentaisi.","Sentähden jos ruoka minun veljeni pahentais, niin en minä ikänäni söisi lihaa, etten minä veljeäni pahentaisi."],[9,1,"Enkö minä ole apostoli? Enkö minä vapaa ole? Enkö minä meidän Herraa Jesusta Kristusta nähnyt? Ettekö te ole minun työni Herrassa?","Enkö minä ole apostoli? Enkö minä vapaa ole? Enkö minä meidän Herraa Jesusta Kristusta nähnyt? Ettekö te ole minun työni Herrassa?"],[9,2,"Ellen minä ole muille apostoli, niin minä tosin teille olen; sillä te olette minun apostolivirkani sinetti Herrassa.","Ellen minä ole muille apostoli, niin minä tosin teille olen; sillä te olette minun apostolivirkani sinetti Herrassa."],[9,3,"Niille, jotka minulta kysyvät, on tämä minun edesvastaukseni:","Niille, jotka minulta kysyvät, on tämä minun edesvastaukseni:"],[9,4,"Eikö meillä ole valta syödä ja juoda?","Eikö meillä ole valta syödä ja juoda?"],[9,5,"Eikö meillä ole valta sisarta vaimona kanssamme ympäri viedä, niinkuin muillakin apostoleilla, ja Herran veljillä, ja Kephaalla?","Eikö meillä ole valta sisarta vaimona kanssamme ympäri viedä, niinkuin muillakin apostoleilla, ja Herran veljillä, ja Kephaalla?"],[9,6,"Eli minullako yksin ja Barnabaalla ei ole valtaa olla työtä tekemättä?","Eli minullako yksin ja Barnabaalla ei ole valtaa olla työtä tekemättä?"],[9,7,"Kuka sotii koskaan omalla kulutuksellansa? Kuka istuttaa viinatarhan ja ei syö sen hedelmästä? Eli kuka karjaa kaitsee ja ei syö karjan rieskasta?","Kuka sotii koskaan omalla kulutuksellansa? Kuka istuttaa viinatarhan ja ei syö sen hedelmästä? Eli kuka karjaa kaitsee ja ei syö karjan rieskasta?"],[9,8,"Puhunenko minä näitä ihmisten tavalla? Eikö myös laki sitä sano?","Puhunenko minä näitä ihmisten tavalla? Eikö myös laki sitä sano?"],[9,9,"Sillä Moseksen laissa on kirjoitettu: Ei sinun pidä sitoman kiinni riihtä tappavan härjän suuta. Sureneeko Jumala härkiä?","Sillä Moseksen laissa on kirjoitettu: Ei sinun pidä sitoman kiinni riihtä tappavan härjän suuta. Sureneeko Jumala härkiä?"],[9,10,"Taikka, eikö hän sitä kaiketi meidän tähtemme sano? sillä meidän tähtemme on se kirjoitettu: että se joka kyntää, hänen pitää toivossa kyntämän, ja joka riihtä tappaa, hänen pitää toivossa riihtä tappaman, että hän toivostansa osalliseksi tulis.","Taikka, eikö hän sitä kaiketi meidän tähtemme sano? sillä meidän tähtemme on se kirjoitettu: että se joka kyntää, hänen pitää toivossa kyntämän, ja joka riihtä tappaa, hänen pitää toivossa riihtä tappaman, että hän toivostansa osalliseksi tulis."],[9,11,"Jos me olemme teille hengellisiä kylväneet; paljoko se on, jos me teidän ruumiillisianne niitämme?","Jos me olemme teille hengellisiä kylväneet; paljoko se on, jos me teidän ruumiillisianne niitämme?"],[9,12,"Jos muut ovat tässä vallassa osalliset teidän tykönänne, miksi emme siis paljoa enemmin? mutta emmepä me ole sitä valtaa pitäneet, vaan me kärsimme kaikkinaisia, ettemme Kristuksen evankeliumille mitään estettä tekisi.","Jos muut ovat tässä vallassa osalliset teidän tykönänne, miksi emme siis paljoa enemmin? mutta emmepä me ole sitä valtaa pitäneet, vaan me kärsimme kaikkinaisia, ettemme Kristuksen evankeliumille mitään estettä tekisi."],[9,13,"Ettekö te tiedä, että ne, jotka uhraavat, ne syövät uhrista, ja ne, jotka alttaria valmistavat, ne alttarista osalliseksi tulevat?","Ettekö te tiedä, että ne, jotka uhraavat, ne syövät uhrista, ja ne, jotka alttaria valmistavat, ne alttarista osalliseksi tulevat?"],[9,14,"Niin on myös Herra säätänyt, että ne, jotka evankeliumia ilmoittavat, pitää evankeliumista elatuksensa saaman.","Niin on myös Herra säätänyt, että ne, jotka evankeliumia ilmoittavat, pitää evankeliumista elatuksensa saaman."],[9,15,"Mutta en minä ole kuitenkaan mitään näistä tehnyt. Vaan en minä sentähden sitä kirjoita, että niin pitäis minun kanssani tapahtuman. Parempi olis minun kuolla kuin että joku minun kerskaamiseni tyhjäksi tekis.","Mutta en minä ole kuitenkaan mitään näistä tehnyt. Vaan en minä sentähden sitä kirjoita, että niin pitäis minun kanssani tapahtuman. Parempi olis minun kuolla kuin että joku minun kerskaamiseni tyhjäksi tekis."],[9,16,"Mutta että minä evankeliumia saarnaan, niin ei minun tarvitse siitä öykätä; sillä minun tulee se tehdä. Voi minua, ellen minä evankeliumia ilmoita!","Mutta että minä evankeliumia saarnaan, niin ei minun tarvitse siitä öykätä; sillä minun tulee se tehdä. Voi minua, ellen minä evankeliumia ilmoita!"],[9,17,"Sillä jos minä sen mielelläni teen, niin minulla on palkka; mutta jos minä ylönmielin sen teen, niin on se virka kuitenkin minulle uskottu.","Sillä jos minä sen mielelläni teen, niin minulla on palkka; mutta jos minä ylönmielin sen teen, niin on se virka kuitenkin minulle uskottu."],[9,18,"Mitäs siis minun palkkani on? että minä Kristuksen evankeliumia saarnaan, ja teen sen ilman vapauttani evankeliumissa.","Mitäs siis minun palkkani on? että minä Kristuksen evankeliumia saarnaan, ja teen sen ilman vapauttani evankeliumissa."],[9,19,"Sillä ehkä minä olen vapaa jokaisesta, niin minä olen kuitenkin minuni tehnyt jokaisen palveliaksi, että minä sitä usiammat voittaisin.","Sillä ehkä minä olen vapaa jokaisesta, niin minä olen kuitenkin minuni tehnyt jokaisen palveliaksi, että minä sitä usiammat voittaisin."],[9,20,"Ja olen Juudalaisille tehty niinkuin Juudalainen, että minä Juudalaiset voittaisin; niille jotka lain alla ovat, niinkuin lain alainen, että minä ne, jotka lain alla ovat, voittaisin;","Ja olen Juudalaisille tehty niinkuin Juudalainen, että minä Juudalaiset voittaisin; niille jotka lain alla ovat, niinkuin lain alainen, että minä ne, jotka lain alla ovat, voittaisin;"],[9,21,"Niille jotka ilman lakia ovat, niinkuin minä ilman lakia olisin, (vaikka en minä ilman lakia Jumalan edessä ole, vaan olen Kristuksen laissa,) että minä ne, jotka ilman lakia ovat, voittaisin;","Niille jotka ilman lakia ovat, niinkuin minä ilman lakia olisin, (vaikka en minä ilman lakia Jumalan edessä ole, vaan olen Kristuksen laissa,) että minä ne, jotka ilman lakia ovat, voittaisin;"],[9,22,"Heikoille olen minä tehty niinkuin heikko, että minä heikot voittaisin. Minä olen kaikille tehty kaikiksi, että minä kaiketi muutamat autuaaksi saattaisin.","Heikoille olen minä tehty niinkuin heikko, että minä heikot voittaisin. Minä olen kaikille tehty kaikiksi, että minä kaiketi muutamat autuaaksi saattaisin."],[9,23,"Mutta sen minä teen evankeliumin tähden, että minä siitä osalliseksi tulisin.","Mutta sen minä teen evankeliumin tähden, että minä siitä osalliseksi tulisin."],[9,24,"Ettekö te tiedä, että ne, jotka kiistassa juoksevat, kaikki tosin he juoksevat, vaan yksi palkan ennättää? Juoskaat siis niin, että te käsittäisitte.","Ettekö te tiedä, että ne, jotka kiistassa juoksevat, kaikki tosin he juoksevat, vaan yksi palkan ennättää? Juoskaat siis niin, että te käsittäisitte."],[9,25,"Mutta jokainen joka kilvoittelee, kaikista hän itsensä pitää pois. Ne tosin sitä varten, että he katoovaisen kruunun saisivat; mutta me katoomattoman.","Mutta jokainen joka kilvoittelee, kaikista hän itsensä pitää pois. Ne tosin sitä varten, että he katoovaisen kruunun saisivat; mutta me katoomattoman."],[9,26,"Mutta en minä niin juokse kuin tietämättömän puoleen, ja minä kilvoittelen, ei niinkuin tuulta pieksäin.","Mutta en minä niin juokse kuin tietämättömän puoleen, ja minä kilvoittelen, ei niinkuin tuulta pieksäin."],[9,27,"Vaan minä kuritan ruumistani ja painan sitä alas, etten minä, joka muille saarnaan, itse hyljättäväksi tulisi.","Vaan minä kuritan ruumistani ja painan sitä alas, etten minä, joka muille saarnaan, itse hyljättäväksi tulisi."],[10,1,"Mutta en minä tahdo sitä teiltä, rakkaat veljet, salata, että meidän isämme ovat kaikki pilven alla olleet ja kaikki meren lävitse vaeltaneet,","Mutta en minä tahdo sitä teiltä, rakkaat veljet, salata, että meidän isämme ovat kaikki pilven alla olleet ja kaikki meren lävitse vaeltaneet,"],[10,2,"Ja kaikki Mosekseen kastetut pilvessä ja meressä.","Ja kaikki Mosekseen kastetut pilvessä ja meressä."],[10,3,"Ja ovat kaikki yhtäläistä hengellistä ruokaa syöneet,","Ja ovat kaikki yhtäläistä hengellistä ruokaa syöneet,"],[10,4,"Ja kaikki yhtäläistä hengellistä juomaa juoneet; sillä he joivat siitä hengellisestä kalliosta, joka heitä seurasi; mutta se kallio oli Kristus.","Ja kaikki yhtäläistä hengellistä juomaa juoneet; sillä he joivat siitä hengellisestä kalliosta, joka heitä seurasi; mutta se kallio oli Kristus."],[10,5,"Mutta ei heistä monta olleet Jumalalle otolliset; sillä he maahan lyötiin korvessa.","Mutta ei heistä monta olleet Jumalalle otolliset; sillä he maahan lyötiin korvessa."],[10,6,"Mutta nämä olivat meille esikuvaksi, ettemme pahaa himoitsisi, niinkuin he himoitsivat.","Mutta nämä olivat meille esikuvaksi, ettemme pahaa himoitsisi, niinkuin he himoitsivat."],[10,7,"Älkäät siis olko epäjumalain palveliat, niinkuin muutamat heistä, niinkuin kirjoitettu on: kansa istui syömään ja juomaan, ja nousi mässäämään.","Älkäät siis olko epäjumalain palveliat, niinkuin muutamat heistä, niinkuin kirjoitettu on: kansa istui syömään ja juomaan, ja nousi mässäämään."],[10,8,"Älkäämme huorin tehkö, niinkuin muutamat heistä itsensä huoruudella saastuttivat ja lankesivat yhtenä päivänä kolmekolmattakymmentä tuhatta.","Älkäämme huorin tehkö, niinkuin muutamat heistä itsensä huoruudella saastuttivat ja lankesivat yhtenä päivänä kolmekolmattakymmentä tuhatta."],[10,9,"Älkäämme Kristusta kiusatko, niinkuin myös muutamat heistä kiusasivat ja surmattiin kärmeiltä.","Älkäämme Kristusta kiusatko, niinkuin myös muutamat heistä kiusasivat ja surmattiin kärmeiltä."],[10,10,"Älkäät napisko, niinkuin muutamat heistä napisivat ja hukattiin kadottajalta.","Älkäät napisko, niinkuin muutamat heistä napisivat ja hukattiin kadottajalta."],[10,11,"Mutta kaikki nämä tulivat heidän kohtaansa esikuvaksi; vaan se on kirjoitettu meille karttamiseksi, joidenka päälle maailman loput tulleet ovat.","Mutta kaikki nämä tulivat heidän kohtaansa esikuvaksi; vaan se on kirjoitettu meille karttamiseksi, joidenka päälle maailman loput tulleet ovat."],[10,12,"Sentähden joka luulee seisovansa, katsokaan, ettei hän lankee.","Sentähden joka luulee seisovansa, katsokaan, ettei hän lankee."],[10,13,"Eipä yksikään kiusaus ole teitä käsittänyt, vaan inhimillinen; mutta Jumala on uskollinen, joka ei salli teitä kiusattaa ylitse teidän voimanne; vaan hän tekee myös kiusauksesta lopun, että te sen voisitte kärsiä.","Eipä yksikään kiusaus ole teitä käsittänyt, vaan inhimillinen; mutta Jumala on uskollinen, joka ei salli teitä kiusattaa ylitse teidän voimanne; vaan hän tekee myös kiusauksesta lopun, että te sen voisitte kärsiä."],[10,14,"Sentähden, minun rakkaani, paetkaat epäjumalain palvelusta!","Sentähden, minun rakkaani, paetkaat epäjumalain palvelusta!"],[10,15,"Minä puhun niinkuin toimellisille: tuomitkaat te, mitä minä sanon.","Minä puhun niinkuin toimellisille: tuomitkaat te, mitä minä sanon."],[10,16,"Se siunattu kalkki, jota me siunaamme, eikö se ole Kristuksen veren osallisuus? Se leipä, jonka me murramme, eikö se ole Kristuksen ruumiin osallisuus?","Se siunattu kalkki, jota me siunaamme, eikö se ole Kristuksen veren osallisuus? Se leipä, jonka me murramme, eikö se ole Kristuksen ruumiin osallisuus?"],[10,17,"Sillä se on yksi leipä, niin mekin monta olemme yksi ruumis; sillä me kaikki yhdestä leivästä olemme osalliset.","Sillä se on yksi leipä, niin mekin monta olemme yksi ruumis; sillä me kaikki yhdestä leivästä olemme osalliset."],[10,18,"Katsokaat Israelia lihan jälkeen: eikö ne, jotka uhria syövät, ole alttarista osalliset?","Katsokaat Israelia lihan jälkeen: eikö ne, jotka uhria syövät, ole alttarista osalliset?"],[10,19,"Mitäs siis minä sanon, että epäjumalat jotakin ovat, eli jos epäjumalain uhri jotakin on?","Mitäs siis minä sanon, että epäjumalat jotakin ovat, eli jos epäjumalain uhri jotakin on?"],[10,20,"Mutta sen minä sanon: mitä pakanat uhraavat, sen he perkeleille uhraavat ja ei Jumalalle. En minä tahdo, että teidän pitää oleman perkeleistä osalliset.","Mutta sen minä sanon: mitä pakanat uhraavat, sen he perkeleille uhraavat ja ei Jumalalle. En minä tahdo, että teidän pitää oleman perkeleistä osalliset."],[10,21,"Ette taida Herran kalkkia juoda ja perkeleiden kalkkia. Ette taida osalliset olla Herran pöydästä ja perkeleiden pöydästä.","Ette taida Herran kalkkia juoda ja perkeleiden kalkkia. Ette taida osalliset olla Herran pöydästä ja perkeleiden pöydästä."],[10,22,"Eli tahdommeko me Herraa härsytellä? Olemmeko me häntä väkevämmät?","Eli tahdommeko me Herraa härsytellä? Olemmeko me häntä väkevämmät?"],[10,23,"Kaikki tosin ovat minulle luvalliset, vaan ei kaikki ole tarpeelliset. Kaikki ovat minulle luvalliset, mutta ei kaikki tapahdu parannukseksi.","Kaikki tosin ovat minulle luvalliset, vaan ei kaikki ole tarpeelliset. Kaikki ovat minulle luvalliset, mutta ei kaikki tapahdu parannukseksi."],[10,24,"Älkään kenkään omaa parastansa katsoko, vaan toisen.","Älkään kenkään omaa parastansa katsoko, vaan toisen."],[10,25,"Kaikkea, mitä teurashuoneessa myydään, syökäät ja älkäät omantunnon tähden kyselkö.","Kaikkea, mitä teurashuoneessa myydään, syökäät ja älkäät omantunnon tähden kyselkö."],[10,26,"Sillä maa on Herran, ja kaikki mitä siinä on.","Sillä maa on Herran, ja kaikki mitä siinä on."],[10,27,"Mutta kuin joku uskomatoin teitä vieraaksi kutsuu ja te mennä tahdotte, niin syökäät kaikkia, mitä teidän eteenne tuodaan ja älkäät omantunnon tähden kyselkö.","Mutta kuin joku uskomatoin teitä vieraaksi kutsuu ja te mennä tahdotte, niin syökäät kaikkia, mitä teidän eteenne tuodaan ja älkäät omantunnon tähden kyselkö."],[10,28,"Mutta jos joku silloin teille sanois: tämä on epäjumalain uhri, niin älkäät syökö, hänen tähtensä, joka sen ilmoitti, ja omantunnon tähden. Sillä maa on Herran ja kaikki mitä siinä on.","Mutta jos joku silloin teille sanois: tämä on epäjumalain uhri, niin älkäät syökö, hänen tähtensä, joka sen ilmoitti, ja omantunnon tähden. Sillä maa on Herran ja kaikki mitä siinä on."],[10,29,"Mutta minä sanon omastatunnosta: ei sinun, vaan toisen; sillä minkätähden minun vapauteni tuomitaan toisen omaltatunnolta?","Mutta minä sanon omastatunnosta: ei sinun, vaan toisen; sillä minkätähden minun vapauteni tuomitaan toisen omaltatunnolta?"],[10,30,"Sillä koska minä sen kiitoksella nautitsen, miksis minua pilkataan sen edestä, josta minä kiitän?","Sillä koska minä sen kiitoksella nautitsen, miksis minua pilkataan sen edestä, josta minä kiitän?"],[10,31,"Jos te nyt syötte eli juotte, eli mitä te teette, niin tehkäät kaikki Jumalan kunniaksi.","Jos te nyt syötte eli juotte, eli mitä te teette, niin tehkäät kaikki Jumalan kunniaksi."],[10,32,"Olkaat ilman pahennusta sekä Juudalaisille että Grekiläisille ja Jumalan seurakunnalle,","Olkaat ilman pahennusta sekä Juudalaisille että Grekiläisille ja Jumalan seurakunnalle,"],[10,33,"Niinkuin minä kaikissa kaikille kelpaan ja en etsi omaa parastani, vaan monen, että he autuaaksi tulisivat.","Niinkuin minä kaikissa kaikille kelpaan ja en etsi omaa parastani, vaan monen, että he autuaaksi tulisivat."],[11,1,"Olkaat minun seuraajani, niinkuin minäkin Kristuksen.","Olkaat minun seuraajani, niinkuin minäkin Kristuksen."],[11,2,"Mutta minä kiitän teitä, rakkaat veljeni, että te minua kaikissa muistatte, ja että te pidätte ne säädyt, jotka minä teille annoin.","Mutta minä kiitän teitä, rakkaat veljeni, että te minua kaikissa muistatte, ja että te pidätte ne säädyt, jotka minä teille annoin."],[11,3,"Mutta minä tahdon, että teidän pitää tietämän, että Kristus on jokaisen miehen pää; mutta mies on vaimon pää, ja Jumala on Kristuksen pää.","Mutta minä tahdon, että teidän pitää tietämän, että Kristus on jokaisen miehen pää; mutta mies on vaimon pää, ja Jumala on Kristuksen pää."],[11,4,"Jokainen mies, joka rukoilee eli propheteeraa, ja pitää jotakin päänsä päällä, se häpäisee päänsä.","Jokainen mies, joka rukoilee eli propheteeraa, ja pitää jotakin päänsä päällä, se häpäisee päänsä."],[11,5,"Mutta jokainen vaimo, joka rukoilee eli propheteeraa peittämättömällä päällä, se häpäisee päänsä; sillä se on niinkuin se ajeltu olis.","Mutta jokainen vaimo, joka rukoilee eli propheteeraa peittämättömällä päällä, se häpäisee päänsä; sillä se on niinkuin se ajeltu olis."],[11,6,"Sillä ellei vaimo anna itsiänsä peittää, niin kerittäkään myös hänen hiuksensa; vaan että se on ruma, että vaimon pitäis keritty eli ajeltu oleman, niin peittäkään päänsä.","Sillä ellei vaimo anna itsiänsä peittää, niin kerittäkään myös hänen hiuksensa; vaan että se on ruma, että vaimon pitäis keritty eli ajeltu oleman, niin peittäkään päänsä."],[11,7,"Mutta ei miehen pidä päätänsä peittämän, sillä hän on Jumalan kuva ja kunnia; mutta vaimo on miehen kunnia.","Mutta ei miehen pidä päätänsä peittämän, sillä hän on Jumalan kuva ja kunnia; mutta vaimo on miehen kunnia."],[11,8,"Sillä ei mies ole vaimosta, mutta vaimo on miehestä.","Sillä ei mies ole vaimosta, mutta vaimo on miehestä."],[11,9,"Ja ei mies ole luotu vaimon tähden, mutta vaimo on luotu miehen tähden.","Ja ei mies ole luotu vaimon tähden, mutta vaimo on luotu miehen tähden."],[11,10,"Sentähden pitää vaimon pitämän voiman päänsä päällä enkelitten tähden;","Sentähden pitää vaimon pitämän voiman päänsä päällä enkelitten tähden;"],[11,11,"Muutoin ei ole mies paitsi vaimoa, eikä vaimo paitsi miestä, Herrassa,","Muutoin ei ole mies paitsi vaimoa, eikä vaimo paitsi miestä, Herrassa,"],[11,12,"Sillä niinkuin vaimo on miehestä, niin on myös mies vaimon kautta; mutta kaikki Jumalasta.","Sillä niinkuin vaimo on miehestä, niin on myös mies vaimon kautta; mutta kaikki Jumalasta."],[11,13,"Tuomitkaat itse keskenänne: onko se kaunis, että vaimo avopäin Jumalaa rukoilee?","Tuomitkaat itse keskenänne: onko se kaunis, että vaimo avopäin Jumalaa rukoilee?"],[11,14,"Eikö luontokin sitä teille opeta, että se on miehelle häpiäksi, jos hänellä on pitkät hiukset?","Eikö luontokin sitä teille opeta, että se on miehelle häpiäksi, jos hänellä on pitkät hiukset?"],[11,15,"Mutta vaimolle on se kunniaksi, että hänellä on pitkät hiukset; sillä hiukset ovat hänelle peitteeksi annetut.","Mutta vaimolle on se kunniaksi, että hänellä on pitkät hiukset; sillä hiukset ovat hänelle peitteeksi annetut."],[11,16,"Mutta jos joku näkyy riitainen olevan, ei meillä eikä Jumalan seurakunnilla se tapa ole.","Mutta jos joku näkyy riitainen olevan, ei meillä eikä Jumalan seurakunnilla se tapa ole."],[11,17,"Mutta kuin minä tätä teille ilmoitan, en minä teitä kiitä, ettette kokoon tule parannukseksi, vaan pahennukseksi.","Mutta kuin minä tätä teille ilmoitan, en minä teitä kiitä, ettette kokoon tule parannukseksi, vaan pahennukseksi."],[11,18,"Sillä ensin, kuin te seurakuntaan tulette, niin minä kuulen eripuraisuudet olevan seassanne; jonka minä myös puolittain uskon.","Sillä ensin, kuin te seurakuntaan tulette, niin minä kuulen eripuraisuudet olevan seassanne; jonka minä myös puolittain uskon."],[11,19,"Sillä teidän seassanne pitää myös eriseurat oleman, että ne, jotka koetellut ovat, teidän seassanne ilmoitettaisiin.","Sillä teidän seassanne pitää myös eriseurat oleman, että ne, jotka koetellut ovat, teidän seassanne ilmoitettaisiin."],[11,20,"Kuin te siis kokoon tulette yhteen, ei se ole Herran ehtoollista pitää.","Kuin te siis kokoon tulette yhteen, ei se ole Herran ehtoollista pitää."],[11,21,"Sillä jokainen ennättää syödä oman ehtoollisensa, yksi isoo, toinen juovuksissa on.","Sillä jokainen ennättää syödä oman ehtoollisensa, yksi isoo, toinen juovuksissa on."],[11,22,"Vai eikö teillä huoneita ole, joissa te syödä ja juoda saatte? Taikka katsotteko te ylön Jumalan seurakunnan ja häpäisette ne, joilla ei mitään ole? Mitä minun pitää teille sanoman? Pitääkö minun teitä kiittämän? Tässä en minä kiitä.","Vai eikö teillä huoneita ole, joissa te syödä ja juoda saatte? Taikka katsotteko te ylön Jumalan seurakunnan ja häpäisette ne, joilla ei mitään ole? Mitä minun pitää teille sanoman? Pitääkö minun teitä kiittämän? Tässä en minä kiitä."],[11,23,"Sillä minä olen sen Herralta saanut, jonka minä myös teille annoin. Sillä Herra Jesus, sinä yönä, jona hän petettiin, otti leivän,","Sillä minä olen sen Herralta saanut, jonka minä myös teille annoin. Sillä Herra Jesus, sinä yönä, jona hän petettiin, otti leivän,"],[11,24,"Ja kiitti, mursi ja sanoi: ottakaat, syökäät! tämä on minun ruumiini, joka teidän edestänne murretaan: se tehkäät minun muistokseni;","Ja kiitti, mursi ja sanoi: ottakaat, syökäät! tämä on minun ruumiini, joka teidän edestänne murretaan: se tehkäät minun muistokseni;"],[11,25,"Niin myös kalkin ehtoollisen jälkeen ja sanoi: tämä kalkki on se Uusi Testamentti minun veressäni; se tehkäät, niin usein kuin te juotte, minun muistokseni.","Niin myös kalkin ehtoollisen jälkeen ja sanoi: tämä kalkki on se Uusi Testamentti minun veressäni; se tehkäät, niin usein kuin te juotte, minun muistokseni."],[11,26,"Sillä niin usein kuin te syötte tästä leivästä ja juotte tästä kalkista, pitää teidän Herran kuoleman julistaman, siihenasti kuin hän tulee.","Sillä niin usein kuin te syötte tästä leivästä ja juotte tästä kalkista, pitää teidän Herran kuoleman julistaman, siihenasti kuin hän tulee."],[11,27,"Sentähden joka kelvottomasti syö tästä leivästä ja juo Herran kalkista, se on vikapää Herran ruumiiseen ja vereen.","Sentähden joka kelvottomasti syö tästä leivästä ja juo Herran kalkista, se on vikapää Herran ruumiiseen ja vereen."],[11,28,"Mutta koetelkaan ihminen itsiänsä, ja niin syökään tästä leivästä ja juokaan tästä kalkista.","Mutta koetelkaan ihminen itsiänsä, ja niin syökään tästä leivästä ja juokaan tästä kalkista."],[11,29,"Sillä joka syö taikka juo kelvottomasti, hän syö ja juo tuomion itsellensä, ettei hän Herran ruumista eroita.","Sillä joka syö taikka juo kelvottomasti, hän syö ja juo tuomion itsellensä, ettei hän Herran ruumista eroita."],[11,30,"Sentähden on myös monta heikkoa ja sairasta teidän seassanne, ja moni makaa.","Sentähden on myös monta heikkoa ja sairasta teidän seassanne, ja moni makaa."],[11,31,"Sillä jos me itsemme tuomitsisimme, niin emme ensinkään tuomittaisi.","Sillä jos me itsemme tuomitsisimme, niin emme ensinkään tuomittaisi."],[11,32,"Vaan kuin me tuomitaan, niin me Herralta kuritetaan, ettemme maailman kanssa kadotettaisi.","Vaan kuin me tuomitaan, niin me Herralta kuritetaan, ettemme maailman kanssa kadotettaisi."],[11,33,"Sentähden, rakkaat veljeni! kuin te kokoon tulette syömään, niin odottakaat toinen toistanne.","Sentähden, rakkaat veljeni! kuin te kokoon tulette syömään, niin odottakaat toinen toistanne."],[11,34,"Mutta jos joku isoo, hän syököön kotonansa, ettette kokoon tulisi kadotukseksi. Ne muut minä tultuani tahdon toimittaa.","Mutta jos joku isoo, hän syököön kotonansa, ettette kokoon tulisi kadotukseksi. Ne muut minä tultuani tahdon toimittaa."],[12,1,"Mutta hengellisistä lahjoista, rakkaat veljet, en minä tahdo teiltä salata.","Mutta hengellisistä lahjoista, rakkaat veljet, en minä tahdo teiltä salata."],[12,2,"Te tiedätte, että te olette pakanat olleet ja käyneet mykkäin epäjumalain tykö, niinkuin te viedyt olitte.","Te tiedätte, että te olette pakanat olleet ja käyneet mykkäin epäjumalain tykö, niinkuin te viedyt olitte."],[12,3,"Sentähden teen minä teille tiettäväksi, ettei yksikään, joka Jumalan Hengen kautta puhuu, Jesusta kiroile: ja ei yksikään taida Jesusta kutsua Herraksi, vaan Pyhän Hengen kautta.","Sentähden teen minä teille tiettäväksi, ettei yksikään, joka Jumalan Hengen kautta puhuu, Jesusta kiroile: ja ei yksikään taida Jesusta kutsua Herraksi, vaan Pyhän Hengen kautta."],[12,4,"Lahjat ovat moninaiset, mutta yksi on Henki;","Lahjat ovat moninaiset, mutta yksi on Henki;"],[12,5,"Ja virat ovat moninaiset, mutta yksi on Herra.","Ja virat ovat moninaiset, mutta yksi on Herra."],[12,6,"Ja voimat ovat moninaiset, mutta yksi on Jumala, joka kaikki kaikissa vaikuttaa.","Ja voimat ovat moninaiset, mutta yksi on Jumala, joka kaikki kaikissa vaikuttaa."],[12,7,"Mutta jokaiselle annetaan Hengen ilmoitus hyödytykseksi.","Mutta jokaiselle annetaan Hengen ilmoitus hyödytykseksi."],[12,8,"Sillä yhdelle annetaan Hengen kautta puhua viisaudesta, toiselle puhua tiedosta, sen yhden Hengen kautta:","Sillä yhdelle annetaan Hengen kautta puhua viisaudesta, toiselle puhua tiedosta, sen yhden Hengen kautta:"],[12,9,"Mutta toiselle usko siitä yhdestä Hengestä: toiselle lahjat terveeksi tehdä siinä yhdessä Hengessä:","Mutta toiselle usko siitä yhdestä Hengestä: toiselle lahjat terveeksi tehdä siinä yhdessä Hengessä:"],[12,10,"Toiselle voimallisia töitä tehdä, toiselle ennustus, toiselle henget eroittaa, toiselle moninaiset kielet, toiselle moninaisten kielten selitys.","Toiselle voimallisia töitä tehdä, toiselle ennustus, toiselle henget eroittaa, toiselle moninaiset kielet, toiselle moninaisten kielten selitys."],[12,11,"Mutta nämät kaikki se yksi Henki vaikuttaa, jakaen kullekin omansa niinkuin hän tahtoo.","Mutta nämät kaikki se yksi Henki vaikuttaa, jakaen kullekin omansa niinkuin hän tahtoo."],[12,12,"Sillä niinkuin ruumis on yksi, ja hänellä on monta jäsentä, mutta kaikki ruumiin jäsenet, ehkä heitä on usia, ovat kuitenkin yksi ruumis; niin on myös Kristus.","Sillä niinkuin ruumis on yksi, ja hänellä on monta jäsentä, mutta kaikki ruumiin jäsenet, ehkä heitä on usia, ovat kuitenkin yksi ruumis; niin on myös Kristus."],[12,13,"Sillä me olemme myös yhdessä Hengessä kaikki yhdeksi ruumiiksi kastetut, sekä Juudalaiset että Grekiläiset, sekä orjat että vapaat, ja kaikki me olemme yhteen Henkeen juotetut.","Sillä me olemme myös yhdessä Hengessä kaikki yhdeksi ruumiiksi kastetut, sekä Juudalaiset että Grekiläiset, sekä orjat että vapaat, ja kaikki me olemme yhteen Henkeen juotetut."],[12,14,"Sillä ei ruumis ole yksi jäsen, vaan usia.","Sillä ei ruumis ole yksi jäsen, vaan usia."],[12,15,"Jos jalka sanois: en minä ole käsi, sentähden en minä ole ruumiista: eikö hän senvuoksi ole ruumiista?","Jos jalka sanois: en minä ole käsi, sentähden en minä ole ruumiista: eikö hän senvuoksi ole ruumiista?"],[12,16,"Ja jos korva sanois: en minä ole silmä, sentähden en minä ole ruumiista: eikö hän senvuoksi ruumiista ole?","Ja jos korva sanois: en minä ole silmä, sentähden en minä ole ruumiista: eikö hän senvuoksi ruumiista ole?"],[12,17,"Jos koko ruumis silmänä olis, kussas siis kuulo? Jos se kaikki kuulona, kussas siis haisto?","Jos koko ruumis silmänä olis, kussas siis kuulo? Jos se kaikki kuulona, kussas siis haisto?"],[12,18,"Mutta nyt on Jumala pannut jäsenet erinänsä itsekunkin ruumiissa niinkuin hän on tahtonut.","Mutta nyt on Jumala pannut jäsenet erinänsä itsekunkin ruumiissa niinkuin hän on tahtonut."],[12,19,"Vai jos kaikki olisivat yksi jäsen, kussa sitte ruumis olis?","Vai jos kaikki olisivat yksi jäsen, kussa sitte ruumis olis?"],[12,20,"Mutta nyt on monta jäsentä, vaan yksi ruumis.","Mutta nyt on monta jäsentä, vaan yksi ruumis."],[12,21,"Mutta ei silmä taida kädelle sanoa: en minä sinua tarvitse, eli taas pää jaloille: en minä teitä tarvitse.","Mutta ei silmä taida kädelle sanoa: en minä sinua tarvitse, eli taas pää jaloille: en minä teitä tarvitse."],[12,22,"Vaan paljoa enemmin ne ruumiin jäsenet, jotka heikommaksi näkyvät, ovat tarpeelliset.","Vaan paljoa enemmin ne ruumiin jäsenet, jotka heikommaksi näkyvät, ovat tarpeelliset."],[12,23,"Ja jotka me luulemme häpiällisemmäksi ruumiissa, niiden päälle me enimmän kunnian panemme; ja jotka häijymmäksi näkyvät, niillä on enin kaunistusta:","Ja jotka me luulemme häpiällisemmäksi ruumiissa, niiden päälle me enimmän kunnian panemme; ja jotka häijymmäksi näkyvät, niillä on enin kaunistusta:"],[12,24,"Sillä jotka meissä kauniit ovat, ei ne mitään tarvitse; mutta Jumala on ruumiin kokoon liittänyt ja sille puuttuvaiselle enemmän kunnian antanut,","Sillä jotka meissä kauniit ovat, ei ne mitään tarvitse; mutta Jumala on ruumiin kokoon liittänyt ja sille puuttuvaiselle enemmän kunnian antanut,"],[12,25,"Ettei eripuraisuutta ruumiissa olisi; vaan kaikki jäsenet pitää toinen toisestansa surun pitämän.","Ettei eripuraisuutta ruumiissa olisi; vaan kaikki jäsenet pitää toinen toisestansa surun pitämän."],[12,26,"Ja jos yksi jäsen kärsii jotakin, niin kaikki muut jäsenet kanssa kärsivät, ja jos yksi jäsen kunniassa pidetään, niin kaikki jäsenet myös riemuitsevat.","Ja jos yksi jäsen kärsii jotakin, niin kaikki muut jäsenet kanssa kärsivät, ja jos yksi jäsen kunniassa pidetään, niin kaikki jäsenet myös riemuitsevat."],[12,27,"Mutta te olette Kristuksen ruumis ja jäsenet, jokainen osansa jälkeen.","Mutta te olette Kristuksen ruumis ja jäsenet, jokainen osansa jälkeen."],[12,28,"Ja Jumala on pannut seurakuntaan ensin apostolit, sitte prophetat, senjälkeen opettajat, sitte voimalliset työt, jälleen parantamisen lahjat, avut, hallitukset, moninaiset kielet.","Ja Jumala on pannut seurakuntaan ensin apostolit, sitte prophetat, senjälkeen opettajat, sitte voimalliset työt, jälleen parantamisen lahjat, avut, hallitukset, moninaiset kielet."],[12,29,"Ovatko kaikki apostolit? Ovatko kaikki prophetat? Ovatko kaikki opettajat? Onko kaikilla voimalliset työt?","Ovatko kaikki apostolit? Ovatko kaikki prophetat? Ovatko kaikki opettajat? Onko kaikilla voimalliset työt?"],[12,30,"Onko kaikilla parantamisen lahjat? Puhuvatko kaikki moninaisilla kielillä? Taitavatko kaikki selittää?","Onko kaikilla parantamisen lahjat? Puhuvatko kaikki moninaisilla kielillä? Taitavatko kaikki selittää?"],[12,31,"Mutta noudattakaat te paraita lahjoja. Ja vielä minä teille korkiamman tien osoitan.","Mutta noudattakaat te paraita lahjoja. Ja vielä minä teille korkiamman tien osoitan."],[13,1,"Jos minä ihmisten ja enkelein kielillä puhuisin, ja ei minulla olisi rakkautta, niin minä olisin kuin helisevä vaski tai kilisevä kulkuinen.","Jos minä ihmisten ja enkelein kielillä puhuisin, ja ei minulla olisi rakkautta, niin minä olisin kuin helisevä vaski tai kilisevä kulkuinen."],[13,2,"Ja jos minä propheteerata taitaisin, ja kaikki salaisuudet tietäisin ja kaiken tiedon, ja minulla olis kaikki usko, niin että minä vuoret siirtäisin, ja ei olisi minulla rakkautta, niin en minä mitään olisi.","Ja jos minä propheteerata taitaisin, ja kaikki salaisuudet tietäisin ja kaiken tiedon, ja minulla olis kaikki usko, niin että minä vuoret siirtäisin, ja ei olisi minulla rakkautta, niin en minä mitään olisi."],[13,3,"Ja jos minä kaiken tavarani kuluttaisin köyhäin ravinnoksi, ja jos minä antaisin ruumiini poltettaa, ja ei olisi minulla rakkautta, niin ei se olisi minulle mitään hyödyllinen.","Ja jos minä kaiken tavarani kuluttaisin köyhäin ravinnoksi, ja jos minä antaisin ruumiini poltettaa, ja ei olisi minulla rakkautta, niin ei se olisi minulle mitään hyödyllinen."],[13,4,"Rakkaus on kärsivällinen ja laupias. Ei rakkaus kadehdi, ei rakkaus ole tyly, ei hän paisu:","Rakkaus on kärsivällinen ja laupias. Ei rakkaus kadehdi, ei rakkaus ole tyly, ei hän paisu:"],[13,5,"Ei hän käytä itsiänsä sopimattomasti, ei omaansa etsi, ei hän vihaan syty, ei hän pahaa ajattele,","Ei hän käytä itsiänsä sopimattomasti, ei omaansa etsi, ei hän vihaan syty, ei hän pahaa ajattele,"],[13,6,"Ei hän vääryydestä iloitse, mutta hän iloitsee totuudesta:","Ei hän vääryydestä iloitse, mutta hän iloitsee totuudesta:"],[13,7,"Kaikki hän peittää, kaikki hän uskoo, kaikki hän toivoo, kaikki hän kärsii.","Kaikki hän peittää, kaikki hän uskoo, kaikki hän toivoo, kaikki hän kärsii."],[13,8,"Ei rakkaus koskaan väsy; vaikka prophetiat lakkaavat, ja kielet vaikenevat, ja tieto katoo.","Ei rakkaus koskaan väsy; vaikka prophetiat lakkaavat, ja kielet vaikenevat, ja tieto katoo."],[13,9,"Sillä me ymmärrämme puolittain, ja propheteeraamme puolittain.","Sillä me ymmärrämme puolittain, ja propheteeraamme puolittain."],[13,10,"Mutta kuin täydellinen tulee, sitte vajaa lakkaa.","Mutta kuin täydellinen tulee, sitte vajaa lakkaa."],[13,11,"Kuin minä olin lapsi, niin minä puhuin kuin lapsi, minulla oli lapsen mieli ja ajattelin kuin lapsi; mutta sitte kuin minä mieheksi tulin, niin minä hylkäsin lapselliset.","Kuin minä olin lapsi, niin minä puhuin kuin lapsi, minulla oli lapsen mieli ja ajattelin kuin lapsi; mutta sitte kuin minä mieheksi tulin, niin minä hylkäsin lapselliset."],[13,12,"Sillä nyt me näemme niinkuin peilistä tapauksessa, mutta silloin kasvoista kasvoihin: nyt minä tunnen puolittain, vaan silloin minä tunnen niiinkuin minä tuttu olen.","Sillä nyt me näemme niinkuin peilistä tapauksessa, mutta silloin kasvoista kasvoihin: nyt minä tunnen puolittain, vaan silloin minä tunnen niiinkuin minä tuttu olen."],[13,13,"Mutta nyt pysyvät usko, toivo, rakkaus, nämät kolme; vaan rakkaus on suurin niistä.","Mutta nyt pysyvät usko, toivo, rakkaus, nämät kolme; vaan rakkaus on suurin niistä."],[14,1,"Noudattakaat rakkautta, olkaat ahkerat hengellisten lahjain perään; mutta enemmin propheteeraamaan.","Noudattakaat rakkautta, olkaat ahkerat hengellisten lahjain perään; mutta enemmin propheteeraamaan."],[14,2,"Sillä joka kielillä puhuu, ei hän ihmisille puhu, vaan Jumalalle; sillä ei kenkään kuule, vaan hän puhuu salaisuudet hengessä.","Sillä joka kielillä puhuu, ei hän ihmisille puhu, vaan Jumalalle; sillä ei kenkään kuule, vaan hän puhuu salaisuudet hengessä."],[14,3,"Mutta joka propheteeraa, se puhuu ihmisille parannukseksi ja neuvoksi ja lohdutukseksi.","Mutta joka propheteeraa, se puhuu ihmisille parannukseksi ja neuvoksi ja lohdutukseksi."],[14,4,"Joka kielillä puhuu, hän parantaa itsensä; mutta joka propheteeraa, hän seurakunnan parantaa.","Joka kielillä puhuu, hän parantaa itsensä; mutta joka propheteeraa, hän seurakunnan parantaa."],[14,5,"Mutta minä tahtoisin, että te kaikki kielillä puhuisitte, mutta paljoa enemmin, että te propheteeraisitte; sillä se, joka propheteeraa, on suurempi kuin se, joka kielillä puhuu, paitsi sitä jos hän sen selittää, että seurakunta sais siitä parannuksen.","Mutta minä tahtoisin, että te kaikki kielillä puhuisitte, mutta paljoa enemmin, että te propheteeraisitte; sillä se, joka propheteeraa, on suurempi kuin se, joka kielillä puhuu, paitsi sitä jos hän sen selittää, että seurakunta sais siitä parannuksen."],[14,6,"Vaan nyt, rakkaat veljeni! jos minä tulen teidän tykönne kielillä puhuen, mitä minä olisin teille hyödyllinen, ellen minä puhuisi teille eli ilmoituksen kautta, eli tiedon kautta, eli prophetian kautta, taikka opin kautta?","Vaan nyt, rakkaat veljeni! jos minä tulen teidän tykönne kielillä puhuen, mitä minä olisin teille hyödyllinen, ellen minä puhuisi teille eli ilmoituksen kautta, eli tiedon kautta, eli prophetian kautta, taikka opin kautta?"],[14,7,"Kuitenkin ne hengettömät, jotka äänen antavat, joko se on huilu eli kantele, koska ei ne anna eri ääntä itsestänsä, kuinka se tiedetään, mitä huilulla eli mitä kanteleella soitettu on?","Kuitenkin ne hengettömät, jotka äänen antavat, joko se on huilu eli kantele, koska ei ne anna eri ääntä itsestänsä, kuinka se tiedetään, mitä huilulla eli mitä kanteleella soitettu on?"],[14,8,"Ja jos vaskitorvi antaa ymmärtämättömän äänen itsestänsä, kuka tietää sotaan hankita?","Ja jos vaskitorvi antaa ymmärtämättömän äänen itsestänsä, kuka tietää sotaan hankita?"],[14,9,"Niin myös te, jos te kielillä puhutte ja ette puhu selkiästi; kuinka se ymmärretään, mitä puhuttu on? Sillä te puhutte tuuleen.","Niin myös te, jos te kielillä puhutte ja ette puhu selkiästi; kuinka se ymmärretään, mitä puhuttu on? Sillä te puhutte tuuleen."],[14,10,"Moninaiset tosin ovat äänet maailmassa, ja ei yhtään niistä ole äänetöintä;","Moninaiset tosin ovat äänet maailmassa, ja ei yhtään niistä ole äänetöintä;"],[14,11,"Sentähden, ellen minä tiedä äänen tointa, niin minä olen puhujalle outo, ja se, joka puhuu, on myös minulle outo.","Sentähden, ellen minä tiedä äänen tointa, niin minä olen puhujalle outo, ja se, joka puhuu, on myös minulle outo."],[14,12,"Niin tekin, koska te ahkerasti hengellisiä lahjoja etsitte, niin ahkeroitkaat seurakunnan parannukseksi, että teillä kyllä olis.","Niin tekin, koska te ahkerasti hengellisiä lahjoja etsitte, niin ahkeroitkaat seurakunnan parannukseksi, että teillä kyllä olis."],[14,13,"Sentähden, joka kielillä puhuu, se rukoilkaan, että hän sen taitais myös selittää.","Sentähden, joka kielillä puhuu, se rukoilkaan, että hän sen taitais myös selittää."],[14,14,"Sillä jos minä kielillä rukoilen, niin minun henkeni rukoilee, mutta minun mieleni on hedelmätöin.","Sillä jos minä kielillä rukoilen, niin minun henkeni rukoilee, mutta minun mieleni on hedelmätöin."],[14,15,"Kuinkas se siis on? Minä rukoilen hengessä, ja rukoilen myös mielessäni: minä veisaan hengessä, ja veisaan myös mielessäni.","Kuinkas se siis on? Minä rukoilen hengessä, ja rukoilen myös mielessäni: minä veisaan hengessä, ja veisaan myös mielessäni."],[14,16,"Mutta koska sinä hengessä siunaat, kuinkas se, joka oppimattoman siassa on, pitää sinun kiitoksees amen sanoman? sillä ei hän ymmärrä, mitäs sanot.","Mutta koska sinä hengessä siunaat, kuinkas se, joka oppimattoman siassa on, pitää sinun kiitoksees amen sanoman? sillä ei hän ymmärrä, mitäs sanot."],[14,17,"Sinä tosin hyvästi kiität, vaan ei se toinen siitä parane.","Sinä tosin hyvästi kiität, vaan ei se toinen siitä parane."],[14,18,"Minä kiitän minun Jumalaani, että minä taidan usiammalla kielellä puhua kuin te kaikki.","Minä kiitän minun Jumalaani, että minä taidan usiammalla kielellä puhua kuin te kaikki."],[14,19,"Mutta seurakunnassa tahdon minä paremmin viisi sanaa puhua minun mielestäni, muita neuvoakseni, ennen kuin kymmenentuhatta sanaa kielillä.","Mutta seurakunnassa tahdon minä paremmin viisi sanaa puhua minun mielestäni, muita neuvoakseni, ennen kuin kymmenentuhatta sanaa kielillä."],[14,20,"Rakkaat veljet, älkäät olko lapset taidossa; vaan olkaat lapset pahuudessa, mutta olkaat taidossa täydelliset.","Rakkaat veljet, älkäät olko lapset taidossa; vaan olkaat lapset pahuudessa, mutta olkaat taidossa täydelliset."],[14,21,"Laissa on kirjoitettu: minä tahdon puhua tälle kansalle toisilla kielillä ja toisilla huulilla, ja ei he sittekään minua kuule, sanoo Herra.","Laissa on kirjoitettu: minä tahdon puhua tälle kansalle toisilla kielillä ja toisilla huulilla, ja ei he sittekään minua kuule, sanoo Herra."],[14,22,"Niin siis kielet ovat merkiksi, ei niille, jotka uskovat, vaan niille, jotka ei usko; mutta ei prophetiat ole uskottomain, vaan uskovaisten tähden.","Niin siis kielet ovat merkiksi, ei niille, jotka uskovat, vaan niille, jotka ei usko; mutta ei prophetiat ole uskottomain, vaan uskovaisten tähden."],[14,23,"Sentähden jos koko seurakunta yhteen paikkaan kokoontuis ja kaikki puhuisivat kielillä ja sinne tulisivat oppimattomat taikka uskottomat; eikö he teitä mielipuoleksi sanoisi?","Sentähden jos koko seurakunta yhteen paikkaan kokoontuis ja kaikki puhuisivat kielillä ja sinne tulisivat oppimattomat taikka uskottomat; eikö he teitä mielipuoleksi sanoisi?"],[14,24,"Mutta jos te kaikki propheteeraisitte, ja sinne tulis joku uskomatoin taikka oppimatoin, ja hän nuhdeltaisiin kaikilta ja tuomittaisiin kaikilta,","Mutta jos te kaikki propheteeraisitte, ja sinne tulis joku uskomatoin taikka oppimatoin, ja hän nuhdeltaisiin kaikilta ja tuomittaisiin kaikilta,"],[14,25,"Ja niin hänen sydämensä salaudet julki tulisivat, ja hän lankeais kasvoillensa ja rukoilis Jumalaa, tunnustain että Jumala olis totisesti teissä.","Ja niin hänen sydämensä salaudet julki tulisivat, ja hän lankeais kasvoillensa ja rukoilis Jumalaa, tunnustain että Jumala olis totisesti teissä."],[14,26,"Kuinkas se on, rakkaat veljet? Koska te kokoon tulette, niin kullakin teistä on psalmi, hänellä on opetus, hänellä on kieli, hänellä on ilmoitus, hänellä on selitys: ne tapahtukoon kaikki parannukseksi.","Kuinkas se on, rakkaat veljet? Koska te kokoon tulette, niin kullakin teistä on psalmi, hänellä on opetus, hänellä on kieli, hänellä on ilmoitus, hänellä on selitys: ne tapahtukoon kaikki parannukseksi."],[14,27,"Jos joku kielillä puhuu, se puhukaan itse toisena, taikka ensinnäkin itse kolmantena, ja vuorottain, ja yksi sen selittäkään.","Jos joku kielillä puhuu, se puhukaan itse toisena, taikka ensinnäkin itse kolmantena, ja vuorottain, ja yksi sen selittäkään."],[14,28,"Ellei hän selittäjä ole, niin olkaan seurakunnassa ääneti ja puhukaan itsellensä ja Jumalalle.","Ellei hän selittäjä ole, niin olkaan seurakunnassa ääneti ja puhukaan itsellensä ja Jumalalle."],[14,29,"Mutta prophetat puhukaan itse toisena, eli itse kolmantena, ja ne muut tuomitkaan.","Mutta prophetat puhukaan itse toisena, eli itse kolmantena, ja ne muut tuomitkaan."],[14,30,"Ja jos jollekulle tykönä istuvalle ilmoitus tapahtuu, niin olkaan ensimäinen ääneti.","Ja jos jollekulle tykönä istuvalle ilmoitus tapahtuu, niin olkaan ensimäinen ääneti."],[14,31,"Sillä kyllä te kaikki propheteerata taidatte, yksi toisenne perään, että kaikki oppisivat ja tulisivat neuvotuksi.","Sillä kyllä te kaikki propheteerata taidatte, yksi toisenne perään, että kaikki oppisivat ja tulisivat neuvotuksi."],[14,32,"Ja prophetain henget ovat prophetaille alamaiset.","Ja prophetain henget ovat prophetaille alamaiset."],[14,33,"Sillä ei Jumala ole sekaseuraisuuden, vaan rauhan Jumala, niinkuin kaikissa pyhäin seurakunnissa.","Sillä ei Jumala ole sekaseuraisuuden, vaan rauhan Jumala, niinkuin kaikissa pyhäin seurakunnissa."],[14,34,"Teidän vaimonne pitää seurakunnissa ääneti oleman; sillä ei heille ole sallittu puhua, vaan että he ovat alamaiset, niinkuin myös laki sanoo.","Teidän vaimonne pitää seurakunnissa ääneti oleman; sillä ei heille ole sallittu puhua, vaan että he ovat alamaiset, niinkuin myös laki sanoo."],[14,35,"Mutta jos he jotain oppia tahtovat, niin kysykööt miehiltänsä kotona; sillä häijysti se vaimoille sopii, että he seurakunnassa puhuvat.","Mutta jos he jotain oppia tahtovat, niin kysykööt miehiltänsä kotona; sillä häijysti se vaimoille sopii, että he seurakunnassa puhuvat."],[14,36,"Eli onko Jumalan sana teistä tullut? Taikka onko se ainoasti teidän tykönne tullut?","Eli onko Jumalan sana teistä tullut? Taikka onko se ainoasti teidän tykönne tullut?"],[14,37,"Jos joku luulee itsensä prophetaksi, eli hengelliseksi, se tutkikaan, mitä minä teille kirjoitan, että ne ovat Herran käskyt.","Jos joku luulee itsensä prophetaksi, eli hengelliseksi, se tutkikaan, mitä minä teille kirjoitan, että ne ovat Herran käskyt."],[14,38,"Mutta jos joku on tietämätöin, se olkoon tietämätöin.","Mutta jos joku on tietämätöin, se olkoon tietämätöin."],[14,39,"Sentähden rakkaat veljet, ahkeroitkaat propheteerata ja älkäät kieltäkö kielillä puhumasta.","Sentähden rakkaat veljet, ahkeroitkaat propheteerata ja älkäät kieltäkö kielillä puhumasta."],[14,40,"Kaikki tapahtukoon soveliaasti ja säädyllisesti.","Kaikki tapahtukoon soveliaasti ja säädyllisesti."],[15,1,"Mutta minä teen teille tiettäväksi, rakkaat veljet, sen evankeliumin, jonka minä teille ilmoitin, jonka te myös saaneet olette, jossa te myös seisotte,","Mutta minä teen teille tiettäväksi, rakkaat veljet, sen evankeliumin, jonka minä teille ilmoitin, jonka te myös saaneet olette, jossa te myös seisotte,"],[15,2,"Jonka kautta te myös autuaaksi tulette, jos te sen pidätte, minkä minä teille olen ilmoittanut, ellette hukkaan ole uskoneet.","Jonka kautta te myös autuaaksi tulette, jos te sen pidätte, minkä minä teille olen ilmoittanut, ellette hukkaan ole uskoneet."],[15,3,"Sillä minä olen sen ensin teille antanut, jonka minä myös saanut olen, että Kristus on kuollut meidän synteimme tähden, Raamattuin jälkeen,","Sillä minä olen sen ensin teille antanut, jonka minä myös saanut olen, että Kristus on kuollut meidän synteimme tähden, Raamattuin jälkeen,"],[15,4,"Ja että hän oli haudattu ja nousi ylös kolmantena päivänä Raamattuin jälkeen,","Ja että hän oli haudattu ja nousi ylös kolmantena päivänä Raamattuin jälkeen,"],[15,5,"Ja että hän nähtiin Kephaalta ja sitte kahdeltatoistakymmeneltä.","Ja että hän nähtiin Kephaalta ja sitte kahdeltatoistakymmeneltä."],[15,6,"Senjälkeen hän nähtiin usiammalta kuin viideltäsadalta veljeltä yhdellä haavalla, joista monta vielä elävät, mutta muutamat ovat nukkuneet.","Senjälkeen hän nähtiin usiammalta kuin viideltäsadalta veljeltä yhdellä haavalla, joista monta vielä elävät, mutta muutamat ovat nukkuneet."],[15,7,"Sitälähin nähtiin hän Jakobilta ja sen jälkeen kaikilta apostoleilta.","Sitälähin nähtiin hän Jakobilta ja sen jälkeen kaikilta apostoleilta."],[15,8,"Vaan kaikkein viimein on hän myös minulta nähty, niinkuin keskensyntyneeltä.","Vaan kaikkein viimein on hän myös minulta nähty, niinkuin keskensyntyneeltä."],[15,9,"Sillä minä olen kaikkein huonoin apostolitten seassa enkä ole kelvollinen apostoliksi kutsuttaa, että minä olen Jumalan seurakuntaa vainonnut.","Sillä minä olen kaikkein huonoin apostolitten seassa enkä ole kelvollinen apostoliksi kutsuttaa, että minä olen Jumalan seurakuntaa vainonnut."],[15,10,"Mutta Jumalan armosta minä olen se, mikä minä olen, ja hänen armonsa minun kohtaani ei ole tyhjä ollut, vaan minä olen enemmän työtä tehnyt kuin muut kaikki; mutta en kuitenkaan minä, vaan Jumalan armo, joka minussa on.","Mutta Jumalan armosta minä olen se, mikä minä olen, ja hänen armonsa minun kohtaani ei ole tyhjä ollut, vaan minä olen enemmän työtä tehnyt kuin muut kaikki; mutta en kuitenkaan minä, vaan Jumalan armo, joka minussa on."],[15,11,"Olisin siis minä eli he, näin me saarnaamme ja näin te olette myös uskoneet.","Olisin siis minä eli he, näin me saarnaamme ja näin te olette myös uskoneet."],[15,12,"Mutta jos Kristus saarnataan kuolleista nousseeksi ylös; miksi siis teidän seassanne muutamat sanovat, ettei kuolleitten ylösnousemista ole?","Mutta jos Kristus saarnataan kuolleista nousseeksi ylös; miksi siis teidän seassanne muutamat sanovat, ettei kuolleitten ylösnousemista ole?"],[15,13,"Mutta ellei kuolleitten ylösnousemus ole, niin ei Kristuskaan noussut ylös.","Mutta ellei kuolleitten ylösnousemus ole, niin ei Kristuskaan noussut ylös."],[15,14,"Mutta jollei Kristus noussut ylös, niin on meidän saarnamme turha ja teidän uskonne on myös turha,","Mutta jollei Kristus noussut ylös, niin on meidän saarnamme turha ja teidän uskonne on myös turha,"],[15,15,"Ja me löydetään Jumalan vääriksi todistajiksi, että me Jumalaa vastaan todistaneet olemme, että hän on herättänyt ylös Kristuksen, jota ei hän ole herättänyt ylös, ellei kuolleet nouse ylös.","Ja me löydetään Jumalan vääriksi todistajiksi, että me Jumalaa vastaan todistaneet olemme, että hän on herättänyt ylös Kristuksen, jota ei hän ole herättänyt ylös, ellei kuolleet nouse ylös."],[15,16,"Sillä jollei kuolleet nouse ylös, eipä Kristuskaan noussut ole.","Sillä jollei kuolleet nouse ylös, eipä Kristuskaan noussut ole."],[15,17,"Mutta ellei Kristus ole noussut ylös, niin on teidän uskonne turha, ja te olette vielä teidän synneissänne,","Mutta ellei Kristus ole noussut ylös, niin on teidän uskonne turha, ja te olette vielä teidän synneissänne,"],[15,18,"Niin ovat myös ne, jotka Kristuksessa nukkuneet ovat, kadotetut.","Niin ovat myös ne, jotka Kristuksessa nukkuneet ovat, kadotetut."],[15,19,"Jos meillä ainoastaan tässä elämässä on toivo Kristuksen päälle, niin me olemme viheliäisemmät kaikkia muita ihmisiä.","Jos meillä ainoastaan tässä elämässä on toivo Kristuksen päälle, niin me olemme viheliäisemmät kaikkia muita ihmisiä."],[15,20,"Mutta nyt on Kristus kuolleista noussut ylös ja on tullut uutiseksi nukkuneiden seassa.","Mutta nyt on Kristus kuolleista noussut ylös ja on tullut uutiseksi nukkuneiden seassa."],[15,21,"Sillä että ihmisen kautta kuolema on, niin on myös ihmisen kautta kuolleitten ylösnousemus.","Sillä että ihmisen kautta kuolema on, niin on myös ihmisen kautta kuolleitten ylösnousemus."],[15,22,"Sillä niinkuin kaikki Adamissa kuolevat, niin he myös kaikki pitää Kristuksessa eläväksi tehtämän,","Sillä niinkuin kaikki Adamissa kuolevat, niin he myös kaikki pitää Kristuksessa eläväksi tehtämän,"],[15,23,"Mutta kukin järjestyksessänsä: uutinen Kristus, sitte ne, jotka Kristuksen omat ovat, hänen tulemisessansa.","Mutta kukin järjestyksessänsä: uutinen Kristus, sitte ne, jotka Kristuksen omat ovat, hänen tulemisessansa."],[15,24,"Sitte on loppu, koska hän antaa valtakunnan Jumalan ja Isän haltuun, ja panee pois kaiken herrauden ja kaiken vallan ja voiman.","Sitte on loppu, koska hän antaa valtakunnan Jumalan ja Isän haltuun, ja panee pois kaiken herrauden ja kaiken vallan ja voiman."],[15,25,"Sillä hänen tulee hallita, siihenasti kuin hän kaikki vihollisensa panee hänen jalkainsa alle.","Sillä hänen tulee hallita, siihenasti kuin hän kaikki vihollisensa panee hänen jalkainsa alle."],[15,26,"Viimeinen vihollinen, joka pannaan pois, on kuolema.","Viimeinen vihollinen, joka pannaan pois, on kuolema."],[15,27,"Sillä hän on kaikki hänen jalkainsa alle heittänyt. Mutta koska hän sanoo, että kaikki hänen allensa heitetyt ovat, niin on julki, että se on eroitettu, joka hänelle kaikki heitti alle.","Sillä hän on kaikki hänen jalkainsa alle heittänyt. Mutta koska hän sanoo, että kaikki hänen allensa heitetyt ovat, niin on julki, että se on eroitettu, joka hänelle kaikki heitti alle."],[15,28,"Kuin nyt kaikki hänen allensa heitetyksi tulevat, silloin myös itse Poika hänen allensa heitetään, joka kaikki hänen allensa heitti, että Jumala kaikki kaikessa olis.","Kuin nyt kaikki hänen allensa heitetyksi tulevat, silloin myös itse Poika hänen allensa heitetään, joka kaikki hänen allensa heitti, että Jumala kaikki kaikessa olis."],[15,29,"Mitä ne muutoin tekevät, jotka itsensä kastaa antavat kuolleitten päälle, jollei kuolleet nouse ylös? Miksi he siis antavat kuolleitten päälle itseänsä kastaa?","Mitä ne muutoin tekevät, jotka itsensä kastaa antavat kuolleitten päälle, jollei kuolleet nouse ylös? Miksi he siis antavat kuolleitten päälle itseänsä kastaa?"],[15,30,"Miksi myös me joka aika vaarassa olemme?","Miksi myös me joka aika vaarassa olemme?"],[15,31,"Minä kuolen joka päivä meidän kerskaamisen puolesta, joka minulla on Kristuksessa Jesuksessa meidän Herrassamme.","Minä kuolen joka päivä meidän kerskaamisen puolesta, joka minulla on Kristuksessa Jesuksessa meidän Herrassamme."],[15,32,"Jos minä olen ihmisten tavalla Ephesossa petoin kanssa sotinut, mitä se minua auttaa, ellei kuolleet nouse ylös? Syökäämme ja juokaamme; sillä huomenna me kuolemme.","Jos minä olen ihmisten tavalla Ephesossa petoin kanssa sotinut, mitä se minua auttaa, ellei kuolleet nouse ylös? Syökäämme ja juokaamme; sillä huomenna me kuolemme."],[15,33,"Älkäät antako pettää teitänne: pahat jaaritukset turmelevat hyvät tavat.","Älkäät antako pettää teitänne: pahat jaaritukset turmelevat hyvät tavat."],[15,34,"Herätkäät ylös hurskaasti ja älkäät syntiä tehkö; sillä ei muutamat Jumalasta mitään tiedä. Häpiäksi minä näitä teille sanon.","Herätkäät ylös hurskaasti ja älkäät syntiä tehkö; sillä ei muutamat Jumalasta mitään tiedä. Häpiäksi minä näitä teille sanon."],[15,35,"Vaan joku taitais sanoa: kuinkas kuolleet nousevat? ja minkäkaltaisilla ruumiilla he tulevat?","Vaan joku taitais sanoa: kuinkas kuolleet nousevat? ja minkäkaltaisilla ruumiilla he tulevat?"],[15,36,"Sinä tomppeli! Se, minkä sinä kylvät, ei tule eläväksi, ellei hän (ensin) kuole.","Sinä tomppeli! Se, minkä sinä kylvät, ei tule eläväksi, ellei hän (ensin) kuole."],[15,37,"Ja jonka sinä kylvät, ei se ole se ruumis, joka tuleva on, vaan paljas jyvä, nimittäin nisun jyvä eli joku muu.","Ja jonka sinä kylvät, ei se ole se ruumis, joka tuleva on, vaan paljas jyvä, nimittäin nisun jyvä eli joku muu."],[15,38,"Mutta Jumala antaa hänelle ruumiin niinkuin hän tahtoi, ja kullekin siemenelle oman ruumiinsa.","Mutta Jumala antaa hänelle ruumiin niinkuin hän tahtoi, ja kullekin siemenelle oman ruumiinsa."],[15,39,"Ei kaikki liha ole yhtäläinen liha; vaan toinen on ihmisten liha, toinen on karjan liha, toinen on kalain, toinen on lintuin;","Ei kaikki liha ole yhtäläinen liha; vaan toinen on ihmisten liha, toinen on karjan liha, toinen on kalain, toinen on lintuin;"],[15,40,"Ja ovat taivaalliset ruumiit ja maalliset ruumiit; mutta toinen kirkkaus on taivaallisilla ja toinen maallisilla.","Ja ovat taivaalliset ruumiit ja maalliset ruumiit; mutta toinen kirkkaus on taivaallisilla ja toinen maallisilla."],[15,41,"Toinen kirkkaus on auringolla ja toinen kirkkaus kuulla, ja toinen kirkkaus tähdillä; sillä yksi tähti voittaa toisen kirkkaudessa.","Toinen kirkkaus on auringolla ja toinen kirkkaus kuulla, ja toinen kirkkaus tähdillä; sillä yksi tähti voittaa toisen kirkkaudessa."],[15,42,"Niin myös kuolleitten ylösnousemus: se kylvetään turmeluksessa ja nousee ylös turmelematoin,","Niin myös kuolleitten ylösnousemus: se kylvetään turmeluksessa ja nousee ylös turmelematoin,"],[15,43,"Se kylvetään huonona ja nousee ylös kunniassa, se kylvetään heikkoudessa ja nousee ylös väkevyydessä,","Se kylvetään huonona ja nousee ylös kunniassa, se kylvetään heikkoudessa ja nousee ylös väkevyydessä,"],[15,44,"Se kylvetään luonnollinen ruumis ja nousee hengellinen ruumis. Meillä on luonnollinen ruumis, on myös hengellinen ruumis.","Se kylvetään luonnollinen ruumis ja nousee hengellinen ruumis. Meillä on luonnollinen ruumis, on myös hengellinen ruumis."],[15,45,"Niinkuin myös kirjoitettu on: ensimäinen ihminen Adam on tehty eläväksi sieluksi, ja viimeinen Adam eläväksi tekeväiseksi hengeksi.","Niinkuin myös kirjoitettu on: ensimäinen ihminen Adam on tehty eläväksi sieluksi, ja viimeinen Adam eläväksi tekeväiseksi hengeksi."],[15,46,"Mutta hengellinen ei ole ensimäinen, vaan luonnollinen, senjälkeen hengellinen.","Mutta hengellinen ei ole ensimäinen, vaan luonnollinen, senjälkeen hengellinen."],[15,47,"Ensimäinen ihminen on maasta ja maallinen, toinen ihminen on itse Herra taivaasta.","Ensimäinen ihminen on maasta ja maallinen, toinen ihminen on itse Herra taivaasta."],[15,48,"Minkäkaltainen maallinen on, senkaltaiset ovat myös maalliset, ja minkäkaltainen taivaallinen on, senkaltaiset ovat myös taivaalliset.","Minkäkaltainen maallinen on, senkaltaiset ovat myös maalliset, ja minkäkaltainen taivaallinen on, senkaltaiset ovat myös taivaalliset."],[15,49,"Ja niinkuin me olemme kantaneet maallisen kuvaa, niin pitää myös meidän kantaman taivaallisen kuvaa.","Ja niinkuin me olemme kantaneet maallisen kuvaa, niin pitää myös meidän kantaman taivaallisen kuvaa."],[15,50,"Mutta minä sanon, rakkaat veljet, ei liha ja veri taida Jumalan valtakuntaa periä, ja ei turmeltu pidä turmelematointa perimän.","Mutta minä sanon, rakkaat veljet, ei liha ja veri taida Jumalan valtakuntaa periä, ja ei turmeltu pidä turmelematointa perimän."],[15,51,"Katso, minä sanon teille salaisuuden: emme tosin kaikki nuku, vaan kaikki me muutetaan,","Katso, minä sanon teille salaisuuden: emme tosin kaikki nuku, vaan kaikki me muutetaan,"],[15,52,"Ajan rahdussa, silmänräpäyksessä, viimeisellä basunalla; sillä basuna soi, ja kuolleet pitää turmelematoinna nouseman ylös ja me tulemme muutetuksi.","Ajan rahdussa, silmänräpäyksessä, viimeisellä basunalla; sillä basuna soi, ja kuolleet pitää turmelematoinna nouseman ylös ja me tulemme muutetuksi."],[15,53,"Sillä tämä katoova pitää pukeman päällensä katoomattomuuden ja kuoleva pukee päällensä kuolemattomuuden.","Sillä tämä katoova pitää pukeman päällensä katoomattomuuden ja kuoleva pukee päällensä kuolemattomuuden."],[15,54,"Mutta koska katoova pukee päällensä katoomattomuuden ja kuoleva pukee päällensä kuolemattomuuden, silloin täytetään se sana, joka kirjoitettu on: kuolema on nielty voitossa.","Mutta koska katoova pukee päällensä katoomattomuuden ja kuoleva pukee päällensä kuolemattomuuden, silloin täytetään se sana, joka kirjoitettu on: kuolema on nielty voitossa."],[15,55,"Kuolema, kussa on sinun otas? Helvetti, kussa on sinun voittos?","Kuolema, kussa on sinun otas? Helvetti, kussa on sinun voittos?"],[15,56,"Mutta kuoleman ota on synti ja synnin voima on laki.","Mutta kuoleman ota on synti ja synnin voima on laki."],[15,57,"Mutta kiitos olkoon Jumalan, joka meille voiton antanut on meidän Herran Jesuksen Kristuksen kautta!","Mutta kiitos olkoon Jumalan, joka meille voiton antanut on meidän Herran Jesuksen Kristuksen kautta!"],[15,58,"Sentähden, minun rakkaat veljeni, olkaat vahvat, järkähtymättä ja aina yltäkylläiset Herran töissä, tietäen, ettei teidän työnne ole turha Herrassa.","Sentähden, minun rakkaat veljeni, olkaat vahvat, järkähtymättä ja aina yltäkylläiset Herran töissä, tietäen, ettei teidän työnne ole turha Herrassa."],[16,1,"Mutta avun hakemisessa pyhiä varten, niinkuin minä Galatin seurakunnille säätänyt olen, niin te myös tehkäät.","Mutta avun hakemisessa pyhiä varten, niinkuin minä Galatin seurakunnille säätänyt olen, niin te myös tehkäät."],[16,2,"Ensimäisenä sabbattina ottakaan jokainen teistä tykönsä jotakin ja kootkaan varansa jälkeen, ettei äsken silloin, kuin minä tulen, niitä hakemaan ruveta.","Ensimäisenä sabbattina ottakaan jokainen teistä tykönsä jotakin ja kootkaan varansa jälkeen, ettei äsken silloin, kuin minä tulen, niitä hakemaan ruveta."],[16,3,"Mutta kuin minä tullut olen, jotka te kirjoilla valitsette, ne minä tahdon lähettää viemään teidän lahjojanne Jerusalemiin.","Mutta kuin minä tullut olen, jotka te kirjoilla valitsette, ne minä tahdon lähettää viemään teidän lahjojanne Jerusalemiin."],[16,4,"Jos taas niin on sovelias, että minä itse sinne vaellan, niin he saavat minun kanssani vaeltaa.","Jos taas niin on sovelias, että minä itse sinne vaellan, niin he saavat minun kanssani vaeltaa."],[16,5,"Mutta minä tahdon teidän tykönne tulla, kuin minä Makedonian kautta vaellan. (Sillä minun pitää Makedonian lävitse vaeltaman.)","Mutta minä tahdon teidän tykönne tulla, kuin minä Makedonian kautta vaellan. (Sillä minun pitää Makedonian lävitse vaeltaman.)"],[16,6,"Mutta teidän tyköänne minä mitämaks viivyn eli myös talvea pidän, että te minua saattaisitte, kuhunka minä matkustan.","Mutta teidän tyköänne minä mitämaks viivyn eli myös talvea pidän, että te minua saattaisitte, kuhunka minä matkustan."],[16,7,"Sillä en minä nyt mennessäni tahdo teitä nähdä; sillä minä toivon saavani jonkun ajan viipyä teidän tykönänne, jos Herra sallii.","Sillä en minä nyt mennessäni tahdo teitä nähdä; sillä minä toivon saavani jonkun ajan viipyä teidän tykönänne, jos Herra sallii."],[16,8,"Mutta minä tahdon Ephesossa viipyä helluntaihin asti;","Mutta minä tahdon Ephesossa viipyä helluntaihin asti;"],[16,9,"Sillä minulle on suuri ja väkevä ovi avattu, ja on monta vastaanseisojaa.","Sillä minulle on suuri ja väkevä ovi avattu, ja on monta vastaanseisojaa."],[16,10,"Mutta jos Timoteus tulee, niin katsokaat, että hän pelkäämättä olis teidän tykönänne; sillä hän tekee myös Herran työtä niinkuin minäkin.","Mutta jos Timoteus tulee, niin katsokaat, että hän pelkäämättä olis teidän tykönänne; sillä hän tekee myös Herran työtä niinkuin minäkin."],[16,11,"Älkään häntä kenkään katsoko ylön, mutta saattakaat häntä rauhassa minun tyköni tulemaan; sillä minä odotan häntä veljien kanssa.","Älkään häntä kenkään katsoko ylön, mutta saattakaat häntä rauhassa minun tyköni tulemaan; sillä minä odotan häntä veljien kanssa."],[16,12,"Mutta veljestä Apollosta tietäkäät, että minä olen häntä paljon neuvonut veljien kanssa teidän tykönne tulemaan, mutta ei hän nyt tahtonut tulla; kuitenkin on hän tuleva, kuin hänellä sovelias aika on.","Mutta veljestä Apollosta tietäkäät, että minä olen häntä paljon neuvonut veljien kanssa teidän tykönne tulemaan, mutta ei hän nyt tahtonut tulla; kuitenkin on hän tuleva, kuin hänellä sovelias aika on."],[16,13,"Valvokaat, pysykäät uskossa, olkaat urhoolliset, olkaat vahvat!","Valvokaat, pysykäät uskossa, olkaat urhoolliset, olkaat vahvat!"],[16,14,"Kaikki teidän menonne tapahtukoon rakkaudessa.","Kaikki teidän menonne tapahtukoon rakkaudessa."],[16,15,"Mutta minä neuvon teitä, rakkaat veljet: te tunnette Stephanaan perheen, että he ovat alkeet Akajassa ja ovat ruvenneet pyhiä palvelemaan:","Mutta minä neuvon teitä, rakkaat veljet: te tunnette Stephanaan perheen, että he ovat alkeet Akajassa ja ovat ruvenneet pyhiä palvelemaan:"],[16,16,"Että te myös olisitte senkaltaisille alamaiset ja jokaiselle apulaiselle ja auttajalle.","Että te myös olisitte senkaltaisille alamaiset ja jokaiselle apulaiselle ja auttajalle."],[16,17,"Mutta minä iloitsen Stephanaan, Fortunatuksen ja Akaikuksen tulemisesta; sillä he ovat teidän puuttumisenne täyttäneet.","Mutta minä iloitsen Stephanaan, Fortunatuksen ja Akaikuksen tulemisesta; sillä he ovat teidän puuttumisenne täyttäneet."],[16,18,"Sillä he virvoittivat minun henkeni ja teidän; sentähden tuntekaat senkaltaiset.","Sillä he virvoittivat minun henkeni ja teidän; sentähden tuntekaat senkaltaiset."],[16,19,"Teitä tervehtivät Asian seurakunnat. Teitä tervehtivät suuresti Akvila ja Priskilla Herrassa, ja seurakunta, joka heidän huoneessansa on.","Teitä tervehtivät Asian seurakunnat. Teitä tervehtivät suuresti Akvila ja Priskilla Herrassa, ja seurakunta, joka heidän huoneessansa on."],[16,20,"Teitä tervehtivät kaikki veljet. Tervehtikäät toinen toistanne pyhällä suunantamisella.","Teitä tervehtivät kaikki veljet. Tervehtikäät toinen toistanne pyhällä suunantamisella."],[16,21,"Minä Paavali tervehdin teitä omalla kädelläni.","Minä Paavali tervehdin teitä omalla kädelläni."],[16,22,"Joka ei Herraa Jesusta Kristusta rakasta, se olkoon anatema maranata.","Joka ei Herraa Jesusta Kristusta rakasta, se olkoon anatema maranata."],[16,23,"Herran Jesuksen Kristuksen armo olkoon teidän kanssanne!","Herran Jesuksen Kristuksen armo olkoon teidän kanssanne!"],[16,24,"Minun rakkauteni olkoon kaikkein teidän kanssanne Kristuksessa Jesuksessa! Amen!","Minun rakkauteni olkoon kaikkein teidän kanssanne Kristuksessa Jesuksessa! Amen!"]]}};